/* Agrikranti - Bihar FSO Test Series (BTSC Advt. 29/2026 pattern: 100 Q, 120 min, +1/-0.25).
   FSO01-02 free. FSO03+ paid (pack 'fsots', ₹149): encrypted files in tests/fso/, 2 new tests release daily (rel date). */
window.TESTS=(window.TESTS||[]).concat([{"id": "FSO01", "series": "bihar-fso", "title": "Bihar FSO Mock Test 01 - Full Length (FREE)", "dur": 120, "mpq": 1, "neg": 0.25, "free": true, "rel": "2026-11-14", "questions": [{"q": "किस नदी को 'बिहार का शोक' (Sorrow of Bihar) कहा जाता है?\nWhich river is known as the 'Sorrow of Bihar'?", "o": ["गंडक / Gandak", "बागमती / Bagmati", "सोन / Son", "कोसी / Kosi"], "a": 3, "e": "कोसी नदी बार-बार मार्ग बदलती है और उत्तर बिहार में भीषण बाढ़ लाती है, इसलिए इसे 'बिहार का शोक' कहते हैं।", "s": "GS", "lv": "Easy"}, {"q": "भारतीय संविधान का कौन-सा अनुच्छेद राज्य को पोषण स्तर (level of nutrition) और लोक स्वास्थ्य सुधारने का कर्तव्य देता है?\nWhich Article of the Indian Constitution makes it a duty of the State to raise the level of nutrition and improve public health?", "o": ["अनुच्छेद 48 / Article 48", "अनुच्छेद 51A / Article 51A", "अनुच्छेद 39 / Article 39", "अनुच्छेद 47 / Article 47"], "a": 3, "e": "Article 47 (DPSP): पोषण स्तर, जीवन स्तर व लोक स्वास्थ्य सुधारना राज्य का प्राथमिक कर्तव्य। Food safety कानूनों का संवैधानिक आधार यही माना जाता है।", "s": "GS", "lv": "Moderate"}, {"q": "किसी आँकड़े का माध्य (Mean) 40 और मानक विचलन (Standard Deviation) 8 है। उसका विचरण गुणांक (Coefficient of Variation) कितना होगा?\nThe mean of a data set is 40 and its standard deviation is 8. What is its coefficient of variation?", "o": ["20%", "32%", "12.5%", "5%"], "a": 0, "e": "CV = (SD ÷ Mean) × 100 = (8 ÷ 40) × 100 = 20%।", "s": "MA", "lv": "Moderate"}, {"q": "श्रृंखला में अगला पद ज्ञात कीजिए: 3, 8, 15, 24, 35, ?\nFind the next term: 3, 8, 15, 24, 35, ?", "o": ["46", "49", "50", "48"], "a": 3, "e": "पद = n² - 1: 2²-1=3, 3²-1=8 ... 6²-1=35, अतः 7²-1 = 48।", "s": "MA", "lv": "Easy"}, {"q": "आपदा जोखिम न्यूनीकरण के लिए सेंडाई फ्रेमवर्क (Sendai Framework for Disaster Risk Reduction) किस अवधि के लिए अपनाया गया है?\nThe Sendai Framework for Disaster Risk Reduction has been adopted for which period?", "o": ["2015 - 2030", "2020 - 2035", "2010 - 2025", "2005 - 2015"], "a": 0, "e": "Sendai Framework (2015, जापान) की अवधि 2015 - 2030 है; इसने Hyogo Framework (2005 - 2015) का स्थान लिया।", "s": "GS", "lv": "Hard"}, {"q": "पाटलिपुत्र नगर की स्थापना किस शासक ने की थी?\nWho founded the city of Pataliputra?", "o": ["उदायिन / Udayin", "महापद्मनंद / Mahapadma Nanda", "बिम्बिसार / Bimbisara", "अजातशत्रु / Ajatashatru"], "a": 0, "e": "हर्यक वंश के उदायिन ने गंगा-सोन संगम पर पाटलिपुत्र बसाया और राजधानी राजगृह से यहाँ लाई। अजातशत्रु ने यहाँ दुर्ग (पाटलिग्राम) बनवाया था।", "s": "GS", "lv": "Moderate"}, {"q": "महात्मा गांधी का चंपारण सत्याग्रह किस वर्ष हुआ?\nIn which year did Mahatma Gandhi's Champaran Satyagraha take place?", "o": ["1920", "1917", "1915", "1919"], "a": 1, "e": "चंपारण सत्याग्रह (1917) नील किसानों की तिनकठिया प्रथा के विरुद्ध था; यह भारत में गांधीजी का पहला सत्याग्रह था।", "s": "GS", "lv": "Easy"}, {"q": "बिहार दिवस प्रतिवर्ष किस तिथि को मनाया जाता है?\nBihar Diwas is celebrated every year on:", "o": ["1 नवंबर / 1 November", "22 मार्च / 22 March", "26 जनवरी / 26 January", "15 अगस्त / 15 August"], "a": 1, "e": "22 मार्च 1912 को बिहार, बंगाल प्रेसीडेंसी से अलग प्रांत बना; इसी की स्मृति में बिहार दिवस।", "s": "GS", "lv": "Easy"}, {"q": "विक्रमशिला महाविहार की स्थापना किसने की थी?\nWho founded the Vikramshila Mahavihara?", "o": ["कुमारगुप्त / Kumaragupta", "हर्षवर्धन / Harshavardhana", "धर्मपाल / Dharmapala", "देवपाल / Devapala"], "a": 2, "e": "पाल शासक धर्मपाल (8वीं-9वीं सदी) ने भागलपुर के पास विक्रमशिला की स्थापना की। नालंदा की स्थापना कुमारगुप्त प्रथम ने की थी।", "s": "GS", "lv": "Moderate"}, {"q": "सर्वोच्च न्यायालय ने 'भोजन के अधिकार' (Right to Food) को किस अनुच्छेद के अंतर्गत जीवन के अधिकार का हिस्सा माना है?\nThe Supreme Court has read the 'Right to Food' as part of the right to life under which Article?", "o": ["अनुच्छेद 14 / Article 14", "अनुच्छेद 21 / Article 21", "अनुच्छेद 19 / Article 19", "अनुच्छेद 32 / Article 32"], "a": 1, "e": "PUCL बनाम भारत संघ (2001 से) मामले में भोजन के अधिकार को Article 21 (प्राण व दैहिक स्वतंत्रता) से जोड़ा गया।", "s": "GS", "lv": "Moderate"}, {"q": "राष्ट्रीय खाद्य सुरक्षा अधिनियम (National Food Security Act) किस वर्ष लागू हुआ?\nIn which year was the National Food Security Act enacted?", "o": ["2013", "2016", "2006", "2011"], "a": 0, "e": "NFSA 2013: ग्रामीण 75% व शहरी 50% जनसंख्या को सस्ता अनाज। Food Safety and Standards Act 2006 से इसे अलग याद रखें।", "s": "GS", "lv": "Easy"}, {"q": "पंचायती राज को संवैधानिक दर्जा किस संविधान संशोधन द्वारा मिला?\nWhich Constitutional Amendment gave constitutional status to Panchayati Raj?", "o": ["42वाँ / 42nd", "74वाँ / 74th", "61वाँ / 61st", "73वाँ / 73rd"], "a": 3, "e": "73वाँ संशोधन (1992, लागू 1993) पंचायतें, भाग IX व 11वीं अनुसूची; 74वाँ संशोधन नगरपालिकाओं से संबंधित है।", "s": "GS", "lv": "Moderate"}, {"q": "नीति आयोग (NITI Aayog) का गठन कब हुआ?\nWhen was NITI Aayog constituted?", "o": ["1 अप्रैल 2016", "1 जनवरी 2015", "26 जनवरी 2015", "15 अगस्त 2014"], "a": 1, "e": "1 जनवरी 2015 को योजना आयोग के स्थान पर NITI Aayog बना; अध्यक्ष प्रधानमंत्री होते हैं।", "s": "GS", "lv": "Easy"}, {"q": "वाल्मीकि टाइगर रिज़र्व बिहार के किस जिले में स्थित है?\nValmiki Tiger Reserve is located in which district of Bihar?", "o": ["पश्चिम चंपारण / West Champaran", "कैमूर / Kaimur", "पूर्णिया / Purnia", "गया / Gaya"], "a": 0, "e": "वाल्मीकि टाइगर रिज़र्व पश्चिम चंपारण में नेपाल (चितवन) सीमा से लगा बिहार का एकमात्र टाइगर रिज़र्व है।", "s": "GS", "lv": "Easy"}, {"q": "बिहार का पहला रामसर स्थल (Ramsar site) कौन-सा है?\nWhich was the first Ramsar site of Bihar?", "o": ["गोगाबील, कटिहार", "कुशेश्वरस्थान, दरभंगा", "नागी पक्षी विहार, जमुई", "कांवर झील (काबरताल), बेगूसराय"], "a": 3, "e": "कांवर (काबरताल) झील, बेगूसराय को 2020 में बिहार का पहला रामसर स्थल घोषित किया गया।", "s": "GS", "lv": "Moderate"}, {"q": "विटामिन B1 (थायमिन) की कमी से कौन-सा रोग होता है?\nDeficiency of vitamin B1 (thiamine) causes:", "o": ["पेलाग्रा / Pellagra", "रिकेट्स / Rickets", "बेरी-बेरी / Beri-beri", "स्कर्वी / Scurvy"], "a": 2, "e": "B1 - बेरी-बेरी; B3 (niacin) - पेलाग्रा; C - स्कर्वी; D - रिकेट्स। पॉलिश चावल पर निर्भरता से बेरी-बेरी होती है।", "s": "GS", "lv": "Easy"}, {"q": "मानव रक्त का सामान्य pH लगभग कितना होता है?\nThe normal pH of human blood is about:", "o": ["6.4", "7.0", "8.2", "7.4"], "a": 3, "e": "रक्त हल्का क्षारीय (pH 7.35 - 7.45) होता है।", "s": "GS", "lv": "Easy"}, {"q": "ओज़ोन परत को क्षति पहुँचाने वाले पदार्थों को चरणबद्ध समाप्त करने हेतु कौन-सा समझौता है?\nWhich agreement phases out ozone-depleting substances?", "o": ["पेरिस समझौता / Paris Agreement", "रामसर संधि / Ramsar Convention", "मॉन्ट्रियल प्रोटोकॉल / Montreal Protocol", "क्योटो प्रोटोकॉल / Kyoto Protocol"], "a": 2, "e": "मॉन्ट्रियल प्रोटोकॉल (1987) - CFC आदि; क्योटो व पेरिस समझौते ग्रीनहाउस गैसों से संबंधित हैं।", "s": "GS", "lv": "Moderate"}, {"q": "डिजिलॉकर (DigiLocker) का मुख्य उपयोग क्या है?\nDigiLocker is mainly used for:", "o": ["ई-मेल सेवा", "मौसम पूर्वानुमान", "डिजिटल दस्तावेज़ सुरक्षित रखना व साझा करना", "ऑनलाइन भुगतान"], "a": 2, "e": "Digital India के अंतर्गत DigiLocker में प्रमाणपत्र, लाइसेंस आदि डिजिटल रूप में सुरक्षित रहते हैं; यह e-governance का उदाहरण है।", "s": "GS", "lv": "Easy"}, {"q": "राष्ट्रीय आपदा प्रबंधन प्राधिकरण (NDMA) के अध्यक्ष कौन होते हैं?\nWho is the chairperson of the National Disaster Management Authority (NDMA)?", "o": ["राष्ट्रपति", "कैबिनेट सचिव", "गृह मंत्री", "प्रधानमंत्री"], "a": 3, "e": "Disaster Management Act 2005 के अनुसार NDMA के अध्यक्ष प्रधानमंत्री तथा SDMA के अध्यक्ष मुख्यमंत्री होते हैं।", "s": "GS", "lv": "Easy"}, {"q": "GIS का पूर्ण रूप क्या है?\nWhat is the full form of GIS?", "o": ["Global Information System", "Geographic Information System", "Geological Imaging Survey", "General Internet Service"], "a": 1, "e": "Geographic Information System - स्थानिक आँकड़ों का संग्रह, विश्लेषण व मानचित्रण; आपदा प्रबंधन में remote sensing के साथ उपयोगी।", "s": "GS", "lv": "Easy"}, {"q": "दूध : लैक्टोमीटर :: रक्तचाप : ?\nMilk : Lactometer :: Blood pressure : ?", "o": ["स्फिग्मोमैनोमीटर / Sphygmomanometer", "बैरोमीटर / Barometer", "थर्मामीटर / Thermometer", "हाइड्रोमीटर / Hydrometer"], "a": 0, "e": "Lactometer दूध का आपेक्षिक घनत्व मापता है; रक्तचाप Sphygmomanometer से मापा जाता है।", "s": "MA", "lv": "Easy"}, {"q": "यदि किसी कोड में FOOD को GPPE लिखा जाता है, तो SAFE को क्या लिखा जाएगा?\nIf FOOD is coded as GPPE, how is SAFE coded?", "o": ["RZED", "UCHG", "TBGF", "TBFG"], "a": 2, "e": "हर अक्षर +1: S→T, A→B, F→G, E→F = TBGF।", "s": "MA", "lv": "Easy"}, {"q": "आँकड़ों 3, 7, 9, 12, 15, 20 की माध्यिका (Median) क्या है?\nWhat is the median of 3, 7, 9, 12, 15, 20?", "o": ["10.5", "11", "12", "9"], "a": 0, "e": "सम संख्या (6) में माध्यिका = बीच के दो पदों का औसत = (9 + 12) ÷ 2 = 10.5।", "s": "MA", "lv": "Moderate"}, {"q": "A, B की बहन है। C, B की माँ है। D, C का पिता है। A का D से क्या संबंध है?\nA is B's sister. C is B's mother. D is C's father. How is A related to D?", "o": ["पुत्री / Daughter", "नातिन / Granddaughter", "बहन / Sister", "भतीजी / Niece"], "a": 1, "e": "A, C की पुत्री है और C, D की संतान है; अतः A, D की नातिन (granddaughter) है।", "s": "MA", "lv": "Moderate"}, {"q": "एमाइलोपेक्टिन (Amylopectin) में शाखा बिंदुओं (branch points) पर कौन-सा ग्लाइकोसिडिक बंध होता है?\nWhich glycosidic linkage is present at the branch points of amylopectin?", "o": ["α-1,6", "β-1,4", "β-1,6", "α-1,4"], "a": 0, "e": "Amylopectin की मुख्य श्रृंखला α-1,4 और शाखाएँ α-1,6 बंध से जुड़ती हैं। Amylose लगभग रैखिक (α-1,4) होता है; cellulose में β-1,4 बंध।", "s": "FC", "lv": "Easy"}, {"q": "निम्न में से कौन-सी अभिक्रिया अ-एंजाइमी भूरापन (Non-enzymatic browning) का उदाहरण है?\nWhich of the following is an example of non-enzymatic browning?", "o": ["Polyphenol oxidase द्वारा चाय पत्ती का किण्वन", "Maillard reaction (रोटी की crust का भूरा होना)", "कटे आलू का भूरा होना", "कटे सेब का भूरा होना"], "a": 1, "e": "Maillard reaction = reducing sugar + free amino group, गर्म करने पर; कोई enzyme नहीं। कटे सेब/आलू और चाय में browning polyphenol oxidase (enzymatic) से होती है।", "s": "FC", "lv": "Easy"}, {"q": "मक्खन (Butter) की जलअपघटनी विकृतगंधिता (Hydrolytic rancidity) में मुख्य रूप से कौन-सा अम्ल मुक्त होकर दुर्गंध देता है?\nIn hydrolytic rancidity of butter, which acid is mainly released and causes the off-flavour?", "o": ["Oleic acid", "Palmitic acid", "Stearic acid", "Butyric acid"], "a": 3, "e": "Lipase द्वारा triglyceride टूटने से short-chain butyric acid (C4) मुक्त होता है, जो वाष्पशील व तीखी गंध वाला है। Oxidative rancidity में unsaturated fatty acids पर O₂ का आक्रमण होता है।", "s": "FC", "lv": "Moderate"}, {"q": "हरी सब्ज़ियों को अम्लीय माध्यम में अधिक देर पकाने पर क्लोरोफिल जैतूनी-भूरा (olive-brown) हो जाता है। इसका कारण क्या है?\nOn prolonged cooking in acidic medium, chlorophyll turns olive-brown. Why?", "o": ["Chlorophyll का carotene में बदलना", "Mg²⁺ का H⁺ से प्रतिस्थापन होकर pheophytin बनना", "Mg²⁺ का Cu²⁺ से प्रतिस्थापन", "Phytol श्रृंखला का जुड़ना"], "a": 1, "e": "अम्ल में chlorophyll का केंद्रीय Mg²⁺ आयन H⁺ से हट जाता है और olive-brown pheophytin बनता है। Cu²⁺/Zn²⁺ से प्रतिस्थापन चमकीला हरा रंग देता है।", "s": "FC", "lv": "Moderate"}, {"q": "एंथोसायनिन (Anthocyanin) वर्णक के संबंध में कौन-सा युग्म सही है?\nWhich pair is correct regarding anthocyanin pigments?", "o": ["Carotenoid - क्षारीय माध्यम में लाल", "Flavonoid - अम्लीय माध्यम में लाल", "Porphyrin - अम्लीय माध्यम में नीला", "Betalain - अम्लीय माध्यम में पीला"], "a": 1, "e": "Anthocyanins जल में घुलनशील flavonoid वर्णक हैं; अम्लीय pH पर लाल, उदासीन के पास बैंगनी और क्षारीय pH पर नीले/हरे दिखते हैं।", "s": "FC", "lv": "Hard"}, {"q": "लैक्टोज (Lactose) किन दो मोनोसैकेराइड से बनता है?\nLactose is made up of which two monosaccharides?", "o": ["Glucose + Glucose", "Glucose + Galactose", "Fructose + Galactose", "Glucose + Fructose"], "a": 1, "e": "Lactose = glucose + galactose (β-1,4); sucrose = glucose + fructose; maltose = glucose + glucose।", "s": "FC", "lv": "Easy"}, {"q": "निम्न में से कौन-सी शर्करा अपचायी (non-reducing) है?\nWhich of the following is a non-reducing sugar?", "o": ["Lactose", "Sucrose", "Maltose", "Glucose"], "a": 1, "e": "Sucrose में glucose का C1 और fructose का C2 दोनों बंध में लगे होते हैं, कोई मुक्त anomeric carbon नहीं, इसलिए यह Fehling/Benedict को अपचयित नहीं करती।", "s": "FC", "lv": "Moderate"}, {"q": "इनुलिन (Inulin) किस शर्करा का बहुलक (polymer) है?\nInulin is a polymer of:", "o": ["Glucose", "Galactose", "Mannose", "Fructose"], "a": 3, "e": "Inulin fructose का polymer (fructan) है, कासनी/चिकोरी जड़ में; यह dietary fibre और prebiotic की तरह काम करता है।", "s": "FC", "lv": "Moderate"}, {"q": "उच्च मेथॉक्सिल पेक्टिन (High methoxyl pectin) से जैम/जेली में जेल बनने के लिए कौन-सी स्थिति आवश्यक है?\nGel formation with high methoxyl pectin in jam/jelly requires:", "o": ["केवल Ca²⁺ आयन", "क्षारीय pH व कम शर्करा", "अधिक शर्करा (~65%) व अम्लीय pH (~3.0 - 3.5)", "कम शर्करा व उदासीन pH"], "a": 2, "e": "HM pectin को लगभग 65% soluble solids व pH ~3 चाहिए; low methoxyl pectin Ca²⁺ के साथ कम शर्करा में भी जेल बनाता है।", "s": "FC", "lv": "Hard"}, {"q": "ब्रेड का बासी होना (Staling) मुख्यतः किस प्रक्रिया के कारण होता है?\nStaling of bread is mainly due to:", "o": ["Lipid oxidation", "Starch gelatinization", "Starch retrogradation", "Protein hydrolysis"], "a": 2, "e": "ठंडा होने पर amylose/amylopectin अणु फिर से क्रमबद्ध (recrystallize) होते हैं, इसे retrogradation कहते हैं, जिससे ब्रेड कड़ी हो जाती है।", "s": "FC", "lv": "Moderate"}, {"q": "स्टार्च को पानी के साथ गर्म करने पर कणों के फूलकर गाढ़ा पेस्ट बनने की क्रिया क्या कहलाती है?\nSwelling of starch granules on heating with water to form a viscous paste is called:", "o": ["Caramelization", "Gelatinization", "Retrogradation", "Dextrinization"], "a": 1, "e": "Gelatinization में hydrogen bond टूटते हैं, granules पानी सोखकर फूलते हैं और viscosity बढ़ती है।", "s": "FC", "lv": "Easy"}, {"q": "अनाज (Cereals) व दालों (Pulses) में सीमित अमीनो अम्ल (limiting amino acid) का सही युग्म कौन-सा है?\nWhich is the correct pair of limiting amino acids in cereals and pulses respectively?", "o": ["Tryptophan - Leucine", "Valine - Lysine", "Lysine - Methionine", "Methionine - Lysine"], "a": 2, "e": "अनाज में lysine तथा दालों में methionine (sulphur amino acids) कम होते हैं; इसलिए दाल-चावल का मेल प्रोटीन गुणवत्ता सुधारता है।", "s": "FC", "lv": "Moderate"}, {"q": "प्रोटीन विकृतीकरण (Denaturation) के संबंध में सही कथन कौन-सा है?\nWhich statement about protein denaturation is correct?", "o": ["केवल ठंडा करने पर होता है", "Secondary/tertiary संरचना बिगड़ती है, peptide bond बने रहते हैं", "Peptide bonds टूटकर amino acids बनते हैं", "Primary structure नष्ट हो जाता है"], "a": 1, "e": "Denaturation में ताप, अम्ल, क्षार आदि से हाइड्रोजन/डाइसल्फाइड बंध व folding बिगड़ते हैं, पर primary structure (peptide bonds) बना रहता है।", "s": "FC", "lv": "Moderate"}, {"q": "दूध के मुख्य प्रोटीन केसीन (Casein) का समविभव बिंदु (Isoelectric point) लगभग किस pH पर होता है?\nThe isoelectric point of casein is at about pH:", "o": ["3.2", "4.6", "6.6", "7.4"], "a": 1, "e": "pH 4.6 पर casein का net charge शून्य होता है और वह अवक्षेपित होता है; दही/पनीर (अम्ल द्वारा) बनने का यही आधार है। दूध का सामान्य pH ~6.6 होता है।", "s": "FC", "lv": "Hard"}, {"q": "गेहूँ के ग्लूटेन (Gluten) के दो मुख्य प्रोटीन कौन-से हैं?\nWhich are the two main proteins of wheat gluten?", "o": ["Casein और Whey", "Zein और Oryzenin", "Gliadin और Glutenin", "Albumin और Globulin"], "a": 2, "e": "Gliadin लचीलापन (extensibility) तथा glutenin elasticity देता है; zein मक्के का और oryzenin चावल का प्रोटीन है।", "s": "FC", "lv": "Easy"}, {"q": "तेल/वसा का आयोडीन मान (Iodine value) क्या दर्शाता है?\nThe iodine value of an oil/fat indicates:", "o": ["नमी की मात्रा", "Free fatty acid की मात्रा", "असंतृप्तता की मात्रा (degree of unsaturation)", "Peroxide की मात्रा"], "a": 2, "e": "अधिक iodine value = अधिक double bonds, यानी अधिक असंतृप्त तेल (जैसे अलसी तेल); नारियल तेल का iodine value कम होता है।", "s": "FC", "lv": "Easy"}, {"q": "साबुनीकरण मान (Saponification value) अधिक होने का अर्थ है कि वसा में:\nA high saponification value of a fat indicates that it contains:", "o": ["अधिक peroxides", "लंबी श्रृंखला वाले fatty acids", "छोटी श्रृंखला वाले (कम आणविक भार) fatty acids", "अधिक असंतृप्त fatty acids"], "a": 2, "e": "Saponification value fatty acids के औसत आणविक भार के व्युत्क्रमानुपाती है; नारियल तेल व मक्खन (short/medium chain) का मान अधिक होता है।", "s": "FC", "lv": "Hard"}, {"q": "FSSAI के अनुसार तेल व वसा में ट्रांस फैटी अम्ल (Trans fatty acids) की अधिकतम सीमा कितनी है?\nAs per FSSAI, the maximum limit of trans fatty acids in oils and fats is:", "o": ["5% (भार अनुसार)", "2% (भार अनुसार)", "10% (भार अनुसार)", "3% (भार अनुसार)"], "a": 1, "e": "FSSAI ने 1 जनवरी 2022 से तेल व वसा में trans fat की सीमा 2% (by weight) कर दी है। आंशिक hydrogenation (वनस्पति) में trans fat बनता है।", "s": "FC", "lv": "Hard"}, {"q": "निम्न में से कौन-सा प्राकृतिक प्रति-ऑक्सीकारक (natural antioxidant) है?\nWhich of the following is a natural antioxidant?", "o": ["BHA", "Tocopherol (विटामिन E)", "BHT", "TBHQ"], "a": 1, "e": "Tocopherol वनस्पति तेलों में प्राकृतिक रूप से होता है; BHA, BHT, TBHQ कृत्रिम (synthetic) antioxidants हैं।", "s": "FC", "lv": "Easy"}, {"q": "टमाटर का लाल रंग किस वर्णक के कारण होता है?\nThe red colour of tomato is due to:", "o": ["Lycopene", "Betanin", "Chlorophyll", "Anthocyanin"], "a": 0, "e": "Lycopene एक carotenoid (तेल में घुलनशील) है; यह शक्तिशाली antioxidant भी है।", "s": "FC", "lv": "Easy"}, {"q": "चुकंदर (Beetroot) का लाल-बैंगनी रंग किस वर्ग के वर्णक से है?\nThe red-purple colour of beetroot belongs to which class of pigments?", "o": ["Anthocyanins", "Betalains", "Chlorophylls", "Carotenoids"], "a": 1, "e": "चुकंदर में betalains (betacyanin - लाल, betaxanthin - पीला) होते हैं; ये नाइट्रोजन युक्त वर्णक हैं।", "s": "FC", "lv": "Moderate"}, {"q": "एंजाइमी भूरापन करने वाला पॉलीफिनॉल ऑक्सीडेज (Polyphenol oxidase) किस धातु आयन पर निर्भर है?\nPolyphenol oxidase, responsible for enzymatic browning, contains which metal ion?", "o": ["जस्ता / Zinc", "ताँबा / Copper", "मैग्नीशियम / Magnesium", "लोहा / Iron"], "a": 1, "e": "PPO एक copper-containing enzyme है; यह phenols को quinones में बदलता है जो melanin जैसे भूरे वर्णक बनाते हैं।", "s": "FC", "lv": "Hard"}, {"q": "अमीनो अम्ल की अनुपस्थिति में केवल शर्करा को उच्च ताप पर गर्म करने से भूरापन क्या कहलाता है?\nBrowning produced by heating sugars alone at high temperature (without amino acids) is called:", "o": ["Enzymatic browning", "Ascorbic acid browning", "Caramelization", "Maillard reaction"], "a": 2, "e": "Caramelization शर्करा का सीधा तापीय अपघटन है; Maillard के लिए reducing sugar व amino group दोनों चाहिए।", "s": "FC", "lv": "Moderate"}, {"q": "तले हुए आलू (French fries, chips) में बनने वाला संभावित कैंसरकारी यौगिक एक्रिलामाइड (Acrylamide) मुख्यतः किससे बनता है?\nAcrylamide in fried potato products is mainly formed from:", "o": ["Asparagine व reducing sugars", "Lysine व sucrose", "Fatty acids व oxygen", "Starch व nitrate"], "a": 0, "e": "120 °C से ऊपर Maillard reaction में asparagine व reducing sugars (glucose, fructose) से acrylamide बनता है।", "s": "FC", "lv": "Hard"}, {"q": "मिर्च (Chilli) का तीखापन किस यौगिक के कारण होता है?\nThe pungency of chilli is due to:", "o": ["Capsaicin", "Piperine", "Curcumin", "Allicin"], "a": 0, "e": "Capsaicin - मिर्च; piperine - काली मिर्च; allicin - लहसुन; curcumin - हल्दी का पीला रंग।", "s": "FC", "lv": "Moderate"}, {"q": "निम्न में से कौन-सा समूह सबसे कम जल सक्रियता (Water activity, aw) पर वृद्धि कर सकता है?\nWhich group can grow at the lowest water activity (aw)?", "o": ["सामान्य बैक्टीरिया / Most bacteria", "Xerophilic moulds", "Halophilic bacteria", "सामान्य यीस्ट / Most yeasts"], "a": 1, "e": "सामान्य सीमा: अधिकांश बैक्टीरिया ~0.91, अधिकांश यीस्ट ~0.88, अधिकांश मोल्ड ~0.80, halophilic bacteria ~0.75, xerophilic moulds ~0.61। इसलिए सूखे खाद्य (dry fruits, अनाज) पर फफूँद लगती है।", "s": "FM", "lv": "Moderate"}, {"q": "डिब्बाबंदी (Canning) में pH 4.6 को 'अम्लीय' और 'कम-अम्लीय' खाद्य की विभाजन रेखा क्यों माना जाता है?\nWhy is pH 4.6 taken as the dividing line between acid and low-acid foods in canning?", "o": ["इसके नीचे Clostridium botulinum के spores अंकुरित होकर toxin नहीं बना पाते", "इसके नीचे सभी यीस्ट मर जाते हैं", "इसके नीचे Maillard reaction रुक जाता है", "इसके नीचे enzyme पूरी तरह निष्क्रिय हो जाते हैं"], "a": 0, "e": "pH ≤ 4.6 पर C. botulinum वृद्धि/toxin नहीं बनाता, इसलिए अम्लीय खाद्य को हल्का heat treatment पर्याप्त। Low-acid food (pH > 4.6) को 121 °C पर commercial sterilization (botulinum cook) चाहिए।", "s": "FM", "lv": "Moderate"}, {"q": "तापीय प्रसंस्करण में D-value का अर्थ है:\nIn thermal processing, the D-value means:", "o": ["121.1 °C पर कुल sterilization समय", "किसी निश्चित ताप पर सूक्ष्मजीव संख्या को 90% (1 log cycle) घटाने में लगा समय", "वह ताप जिस पर सभी सूक्ष्मजीव मर जाएँ", "D-value को 10 गुना बदलने के लिए आवश्यक ताप परिवर्तन"], "a": 1, "e": "D-value = decimal reduction time (एक log cycle की कमी)। विकल्प C, z-value की परिभाषा है और विकल्प D, F₀ value के निकट है।", "s": "FM", "lv": "Hard"}, {"q": "एफ्लाटॉक्सिन (Aflatoxin) मुख्य रूप से किस कवक द्वारा उत्पन्न होता है?\nAflatoxin is mainly produced by which fungus?", "o": ["Penicillium roqueforti", "Aspergillus flavus", "Fusarium graminearum", "Claviceps purpurea"], "a": 1, "e": "Aflatoxin: Aspergillus flavus व A. parasiticus (मूँगफली, मक्का)। Claviceps = ergot alkaloids, Fusarium = deoxynivalenol/zearalenone।", "s": "FM", "lv": "Easy"}, {"q": "एक भोज के 2 - 4 घंटे बाद लोगों को तीव्र उल्टी हुई। जाँच में खाद्य संभालने वाले की नाक/घाव से जीवाणु और ताप-स्थिर (heat-stable) enterotoxin मिला। संभावित कारक कौन है?\nVomiting began 2 - 4 hours after a feast. A heat-stable enterotoxin and an organism from the food handler's nose/wound were found. The likely agent is:", "o": ["Listeria monocytogenes", "Clostridium perfringens", "Staphylococcus aureus", "Salmonella Typhimurium"], "a": 2, "e": "S. aureus पहले से बना heat-stable enterotoxin देता है, incubation लगभग 1 - 6 घंटे, मुख्य लक्षण उल्टी। Salmonella 6 - 72 घंटे, C. perfringens 8 - 22 घंटे।", "s": "FM", "lv": "Hard"}, {"q": "जीवाणु वृद्धि वक्र (growth curve) की किस अवस्था में वृद्धि दर सर्वाधिक होती है?\nIn which phase of the bacterial growth curve is the growth rate maximum?", "o": ["Lag phase", "Log (exponential) phase", "Death phase", "Stationary phase"], "a": 1, "e": "Log phase में कोशिकाएँ स्थिर दर से द्विगुणित होती हैं; lag phase अनुकूलन की अवस्था है।", "s": "FM", "lv": "Easy"}, {"q": "किसी जीवाणु का generation time 20 मिनट है। 100 कोशिकाओं से 1 घंटे बाद कितनी कोशिकाएँ होंगी?\nA bacterium has a generation time of 20 minutes. Starting with 100 cells, how many cells will be present after 1 hour?", "o": ["600", "300", "800", "1600"], "a": 2, "e": "1 घंटे में 3 generations: N = 100 × 2³ = 800।", "s": "FM", "lv": "Moderate"}, {"q": "कौन-सा खाद्य रोगजनक रेफ्रिजरेटर ताप (लगभग 4 °C) पर भी वृद्धि कर सकता है?\nWhich foodborne pathogen can grow even at refrigeration temperature (about 4 °C)?", "o": ["Staphylococcus aureus", "Listeria monocytogenes", "Clostridium perfringens", "Salmonella Typhi"], "a": 1, "e": "Listeria psychrotrophic है; ठंडे संग्रहित ready-to-eat खाद्य, सॉफ्ट चीज़ में खतरा, गर्भवती महिलाओं के लिए गंभीर।", "s": "FM", "lv": "Moderate"}, {"q": "निम्न में से कौन-से दो वंश (genera) एंडोस्पोर (endospore) बनाते हैं?\nWhich two genera form endospores?", "o": ["Lactobacillus व Streptococcus", "Pseudomonas व Vibrio", "Escherichia व Salmonella", "Bacillus व Clostridium"], "a": 3, "e": "Bacillus (aerobic) व Clostridium (anaerobic) के spores ताप-प्रतिरोधी होते हैं, इसलिए canning में sterilization इन्हीं को लक्ष्य करता है।", "s": "FM", "lv": "Easy"}, {"q": "ग्राम-धनात्मक (Gram positive) जीवाणु ग्राम अभिरंजन में किस रंग के दिखते हैं और क्यों?\nGram-positive bacteria appear in which colour after Gram staining and why?", "o": ["बैंगनी - outer membrane के कारण", "हरे - lipid की अधिकता", "बैंगनी - मोटी peptidoglycan परत", "गुलाबी - पतली peptidoglycan परत"], "a": 2, "e": "मोटी peptidoglycan परत crystal violet-iodine complex रोक लेती है; Gram negative में पतली परत व outer membrane होने से safranin का गुलाबी रंग दिखता है।", "s": "FM", "lv": "Easy"}, {"q": "एक नमूने के 10⁻⁵ तनुकरण (dilution) से 1 mL प्लेट करने पर 150 कॉलोनी मिलीं। मूल नमूने में जीवाणु संख्या कितनी है?\nPlating 1 mL of a 10⁻⁵ dilution gave 150 colonies. What is the count in the original sample?", "o": ["1.5 × 10⁶ CFU/mL", "1.5 × 10⁵ CFU/mL", "1.5 × 10³ CFU/mL", "1.5 × 10⁷ CFU/mL"], "a": 3, "e": "CFU/mL = colonies × dilution factor ÷ volume plated = 150 × 10⁵ ÷ 1 = 1.5 × 10⁷।", "s": "FM", "lv": "Moderate"}, {"q": "'हर्डल टेक्नोलॉजी' (Hurdle technology) की अवधारणा किसने दी?\nWho proposed the concept of 'hurdle technology'?", "o": ["Nicolas Appert", "Louis Pasteur", "Lothar Leistner", "Robert Koch"], "a": 2, "e": "Leistner ने बताया कि कई हल्के अवरोध (aw, pH, ताप, preservatives, Eh) मिलकर सूक्ष्मजीव को रोकते हैं। Appert = canning के जनक।", "s": "FM", "lv": "Hard"}, {"q": "Clostridium botulinum के विष (botulinum toxin) के बारे में सही कथन कौन-सा है?\nWhich statement about botulinum toxin is correct?", "o": ["यह उल्टी-दस्त वाला हल्का रोग देता है", "यह neurotoxin है और लगभग 10 मिनट उबालने पर नष्ट हो जाता है", "यह केवल अम्लीय खाद्य में बनता है", "यह ताप-स्थिर enterotoxin है"], "a": 1, "e": "Botulinum toxin neurotoxin है (flaccid paralysis) पर heat-labile है; जबकि इसके spores अत्यधिक ताप-प्रतिरोधी होते हैं।", "s": "FM", "lv": "Hard"}, {"q": "'फ्राइड राइस सिंड्रोम' (Fried rice syndrome) किस जीवाणु से जुड़ा है?\n'Fried rice syndrome' is associated with:", "o": ["Vibrio cholerae", "Shigella dysenteriae", "Campylobacter jejuni", "Bacillus cereus"], "a": 3, "e": "पके चावल को कमरे के ताप पर रखने से B. cereus के spores अंकुरित होकर heat-stable emetic toxin (cereulide) बनाते हैं।", "s": "FM", "lv": "Moderate"}, {"q": "Salmonella संक्रमण का सबसे सामान्य खाद्य स्रोत कौन-सा है?\nThe most common food source of Salmonella infection is:", "o": ["अचार", "कच्चे अंडे व पोल्ट्री", "डिब्बाबंद फल", "शहद"], "a": 1, "e": "Salmonella मुर्गी, अंडे, कच्चे मांस से फैलती है; अधपके अंडे/चिकन से salmonellosis होता है।", "s": "FM", "lv": "Easy"}, {"q": "ब्रेड में 'रोपीनेस' (Ropiness) किस सूक्ष्मजीव के कारण होती है?\nRopiness in bread is caused by:", "o": ["Rhizopus stolonifer", "Saccharomyces cerevisiae", "Aspergillus niger", "Bacillus subtilis (B. licheniformis)"], "a": 3, "e": "Bacillus के spores baking में बच जाते हैं और ब्रेड के भीतर चिपचिपा, धागेदार पदार्थ बनाते हैं; Rhizopus ब्रेड पर काली फफूँद देता है।", "s": "FM", "lv": "Moderate"}, {"q": "दूध का खट्टा होना (Souring) मुख्यतः किसके कारण होता है?\nSouring of milk is mainly caused by:", "o": ["Yeast", "Clostridium", "Pseudomonas", "Lactic acid bacteria (जैसे Lactococcus lactis)"], "a": 3, "e": "Lactic acid bacteria lactose को lactic acid में बदलते हैं, pH गिरता है और दूध खट्टा होता है।", "s": "FM", "lv": "Easy"}, {"q": "दूध का 'मीठा फटना' (Sweet curdling) किस कारण होता है?\n'Sweet curdling' of milk is caused by:", "o": ["Lipase द्वारा वसा का टूटना", "Lactic acid का अधिक बनना", "Yeast द्वारा alcohol बनना", "Bacillus आदि द्वारा rennin जैसे protease एंजाइम"], "a": 3, "e": "Sweet curdling में अम्ल नहीं बनता, बल्कि Bacillus cereus जैसे जीवों के protease (rennet-like) से casein जमता है।", "s": "FM", "lv": "Hard"}, {"q": "ठंडे संग्रहित ताज़े मांस की सतह पर चिपचिपी परत (slime) प्रायः किस जीवाणु से बनती है?\nSurface slime on chilled fresh meat is usually caused by:", "o": ["Clostridium", "Lactobacillus", "Bifidobacterium", "Pseudomonas"], "a": 3, "e": "Pseudomonas aerobic, psychrotrophic Gram negative जीवाणु है; वायु में रखे ठंडे मांस का प्रमुख spoilage जीव।", "s": "FM", "lv": "Moderate"}, {"q": "सेब के रस (Apple juice) में पाया जाने वाला कवक-विष पैटुलिन (Patulin) मुख्यतः किसके द्वारा बनता है?\nPatulin in apple juice is mainly produced by:", "o": ["Claviceps purpurea", "Fusarium verticillioides", "Aspergillus flavus", "Penicillium expansum"], "a": 3, "e": "Penicillium expansum सेब का नीला सड़न (blue mould rot) करता है और patulin बनाता है।", "s": "FM", "lv": "Moderate"}, {"q": "टूना/मैकेरल मछली खाने से होने वाला स्कॉम्ब्रॉयड विषाक्तता (Scombroid poisoning) किस यौगिक से होता है?\nScombroid poisoning from tuna/mackerel is caused by:", "o": ["Histamine", "Ciguatoxin", "Tetrodotoxin", "Saxitoxin"], "a": 0, "e": "गलत भंडारण से जीवाणु histidine को decarboxylate कर histamine बनाते हैं; यह ताप से नष्ट नहीं होता।", "s": "FM", "lv": "Moderate"}, {"q": "खाद्य में काँच का टुकड़ा किस प्रकार का खतरा (hazard) है?\nA piece of glass in food is which type of hazard?", "o": ["एलर्जिक / Allergenic", "जैविक / Biological", "भौतिक / Physical", "रासायनिक / Chemical"], "a": 2, "e": "भौतिक hazard: काँच, धातु, पत्थर; रासायनिक: कीटनाशी अवशेष, मिलावट; जैविक: जीवाणु, विषाणु, परजीवी।", "s": "FM", "lv": "Easy"}, {"q": "HACCP प्रणाली में कितने सिद्धांत (principles) होते हैं?\nHow many principles are there in the HACCP system?", "o": ["7", "12", "9", "5"], "a": 0, "e": "HACCP के 7 सिद्धांत: hazard analysis, CCP निर्धारण, critical limits, monitoring, corrective action, verification, documentation।", "s": "FM", "lv": "Easy"}, {"q": "दूध के उचित पाश्चुरीकरण की जाँच के लिए कौन-सा एंजाइम परीक्षण किया जाता है?\nWhich enzyme test checks proper pasteurization of milk?", "o": ["Alkaline phosphatase test", "Catalase test", "Lipase test", "Amylase test"], "a": 0, "e": "Alkaline phosphatase, Mycobacterium tuberculosis की तुलना में थोड़ा अधिक ताप-प्रतिरोधी है; पाश्चुरीकृत दूध में इसका negative आना सही पाश्चुरीकरण दर्शाता है।", "s": "FM", "lv": "Moderate"}, {"q": "E. coli O157:H7 संक्रमण की गंभीर जटिलता कौन-सी है?\nA serious complication of E. coli O157:H7 infection is:", "o": ["Botulism", "Typhoid fever", "Hemolytic uremic syndrome (HUS)", "Hepatitis A"], "a": 2, "e": "यह Shiga toxin बनाने वाला E. coli (STEC) है; अधपका कीमा, कच्चा दूध से फैलता है और बच्चों में HUS (गुर्दे की विफलता) कर सकता है।", "s": "FM", "lv": "Moderate"}, {"q": "धान के उबालने (Parboiling) का मुख्य पोषण लाभ क्या है?\nWhat is the main nutritional advantage of parboiling paddy?", "o": ["Amylose का पूरा अपघटन", "B-vitamins (Thiamine आदि) व खनिज भ्रूणपोष (endosperm) में चले जाते हैं", "चावल में protein दोगुना होना", "Bran की मात्रा बढ़ जाती है"], "a": 1, "e": "Soaking - steaming - drying में water-soluble B vitamins व minerals भीतर endosperm में चले जाते हैं, इसलिए polishing में कम नष्ट होते हैं; साथ ही milling में टूटन (broken rice) कम होती है।", "s": "FP", "lv": "Moderate"}, {"q": "दूध का HTST पाश्चुरीकरण (Pasteurization) किस ताप-समय संयोजन पर होता है?\nHTST pasteurization of milk is done at:", "o": ["100 °C, 5 मिनट", "121 °C, 15 मिनट", "72 °C, 15 सेकंड", "63 °C, 30 मिनट"], "a": 2, "e": "HTST = 71.7 - 72 °C पर 15 सेकंड; LTLT (holder) = 63 °C पर 30 मिनट; 121 °C/15 मिनट autoclave sterilization है।", "s": "FP", "lv": "Easy"}, {"q": "पर्लिंग (Pearling) प्रक्रिया मुख्य रूप से किस अनाज से जुड़ी है?\nThe process of pearling is mainly associated with which cereal?", "o": ["बाजरा / Pearl millet", "गेहूँ / Wheat", "जौ / Barley", "मक्का / Maize"], "a": 2, "e": "जौ के husk और bran को abrasion से हटाकर 'pearl barley' बनाया जाता है। नाम में 'pearl' होने के बावजूद बाजरा सही उत्तर नहीं है।", "s": "FP", "lv": "Easy"}, {"q": "दूध के समांगीकरण (Homogenization) का मुख्य उद्देश्य क्या है?\nWhat is the main purpose of homogenization of milk?", "o": ["दूध से lactose हटाना", "दूध की अम्लता बढ़ाना", "सभी रोगजनक जीवाणुओं को नष्ट करना", "वसा गोलिकाओं (fat globules) को छोटा कर क्रीम परत बनने से रोकना"], "a": 3, "e": "उच्च दाब पर छोटे छिद्र से गुजारने पर fat globules लगभग 1 - 2 µm के हो जाते हैं, जिससे cream line नहीं बनती। रोगाणु नाश pasteurization का कार्य है।", "s": "FP", "lv": "Moderate"}, {"q": "नए खाद्य उत्पाद के विकास में 9-बिंदु हेडोनिक स्केल (9-point Hedonic scale) का उपयोग किसके लिए होता है?\nIn product development, the 9-point hedonic scale is used to measure:", "o": ["सूक्ष्मजीव भार", "नमी की मात्रा", "उपभोक्ता की पसंद/स्वीकार्यता (acceptability)", "खाद्य का pH"], "a": 2, "e": "Hedonic scale (1 = Dislike extremely से 9 = Like extremely) एक affective sensory test है, जो उत्पाद की स्वीकार्यता बताता है।", "s": "FP", "lv": "Moderate"}, {"q": "धान की मिलिंग में भूसी हटाने (dehusking) के लिए सामान्यतः कौन-सी मशीन उपयोग होती है?\nWhich machine is commonly used for dehusking paddy in rice milling?", "o": ["Ball mill", "Plate freezer", "Hammer mill", "Rubber roll sheller"], "a": 3, "e": "Rubber roll sheller में दो रोल अलग-अलग गति से घूमकर husk अलग करते हैं, टूटन कम होती है; फिर polisher से bran हटता है।", "s": "FP", "lv": "Moderate"}, {"q": "चावल की भूसी (Rice bran) को तेल निकालने से पहले स्थिरीकरण (stabilization) क्यों आवश्यक है?\nWhy must rice bran be stabilized before oil extraction?", "o": ["रंग गहरा करने हेतु", "Lipase सक्रिय रहने से free fatty acids तेज़ी से बढ़ते हैं", "Protein बढ़ाने हेतु", "Starch हटाने हेतु"], "a": 1, "e": "Milling के बाद lipase तेल को तेज़ी से तोड़ता है (FFA कुछ घंटों में बढ़ता है); इसलिए heat/extrusion stabilization किया जाता है।", "s": "FP", "lv": "Hard"}, {"q": "गेहूँ की मिलिंग से पहले टेम्परिंग (Tempering/Conditioning) का उद्देश्य क्या है?\nWhat is the purpose of tempering wheat before milling?", "o": ["प्रोटीन नष्ट करना", "चोकर (bran) को सख़्त व भ्रूणपोष को नरम कर अलग करना आसान बनाना", "कीट मारना", "दाने को सुखाना"], "a": 1, "e": "नियंत्रित पानी देकर कुछ घंटे रखने से bran कड़ा (कम टूटता) और endosperm भुरभुरा होता है, आटा उपज व गुणवत्ता बढ़ती है।", "s": "FP", "lv": "Moderate"}, {"q": "माल्टिंग (Malting) के मुख्य चरणों का सही क्रम क्या है?\nWhat is the correct sequence of steps in malting?", "o": ["Kilning - Steeping - Germination", "Steeping - Germination - Kilning", "Germination - Steeping - Kilning", "Steeping - Kilning - Germination"], "a": 1, "e": "पहले भिगोना (steeping), फिर अंकुरण (germination) और अंत में सुखाना (kilning)। जौ माल्टिंग के लिए प्रमुख अनाज है।", "s": "FP", "lv": "Easy"}, {"q": "माल्टिंग के दौरान स्टार्च को शर्करा में बदलने वाला मुख्य एंजाइम कौन-सा है?\nWhich enzyme mainly converts starch to sugars during malting?", "o": ["Lipase", "Pectinase", "Protease", "Amylase (Diastase)"], "a": 3, "e": "अंकुरण में α- व β-amylase बनते हैं, जो brewing में starch को maltose में बदलते हैं।", "s": "FP", "lv": "Easy"}, {"q": "मक्के की गीली मिलिंग (Corn wet milling) का मुख्य उत्पाद क्या है?\nThe main product of corn wet milling is:", "o": ["Popcorn", "Grits", "Corn flakes", "Starch"], "a": 3, "e": "Wet milling में steeping (SO₂ युक्त पानी) के बाद starch, gluten, germ (तेल) व fibre अलग होते हैं; dry milling से grits व meal मिलते हैं।", "s": "FP", "lv": "Moderate"}, {"q": "तिलहनों से विलायक निष्कर्षण (Solvent extraction) में प्रायः कौन-सा विलायक प्रयोग होता है?\nWhich solvent is commonly used for solvent extraction of oilseeds?", "o": ["Ethanol", "Methanol", "Hexane", "Acetone"], "a": 2, "e": "Food grade n-hexane कम क्वथनांक (~69 °C) वाला है और तेल को कुशलता से घोलता है; बाद में desolventization से हटाया जाता है।", "s": "FP", "lv": "Easy"}, {"q": "खाद्य तेल शोधन (Oil refining) के चरणों का सही क्रम कौन-सा है?\nWhat is the correct sequence of edible oil refining?", "o": ["Neutralization - Deodorization - Degumming - Bleaching", "Bleaching - Degumming - Neutralization - Deodorization", "Deodorization - Bleaching - Degumming - Neutralization", "Degumming - Neutralization - Bleaching - Deodorization"], "a": 3, "e": "Degumming (phospholipids) → Neutralization (alkali से FFA हटाना) → Bleaching (रंग) → Deodorization (भाप से गंध)।", "s": "FP", "lv": "Moderate"}, {"q": "दाल मिलिंग में छिलका ढीला करने हेतु कौन-सा पूर्व-उपचार (pre-treatment) किया जाता है?\nWhich pre-treatment is used in pulse milling to loosen the husk?", "o": ["Freezing", "Smoking", "Irradiation", "तेल/पानी लगाकर धूप में सुखाना (oil-water treatment)"], "a": 3, "e": "पारंपरिक dry method में तेल या पानी लगाकर सुखाया जाता है, जिससे husk व cotyledon के बीच की gum ढीली होती है।", "s": "FP", "lv": "Moderate"}, {"q": "सोयाबीन का कौन-सा प्रति-पोषक तत्व (anti-nutrient) प्रोटीन पाचन रोकता है और ताप से नष्ट होता है?\nWhich anti-nutrient of soybean inhibits protein digestion and is destroyed by heat?", "o": ["Phytic acid", "Tannin", "Oxalate", "Trypsin inhibitor"], "a": 3, "e": "Trypsin (protease) inhibitor गर्म करने/उबालने से निष्क्रिय होता है; phytate खनिजों (Fe, Zn) की उपलब्धता घटाता है।", "s": "FP", "lv": "Moderate"}, {"q": "चाय प्रसंस्करण में CTC का पूर्ण रूप क्या है?\nIn tea processing, CTC stands for:", "o": ["Clean, Toast, Cure", "Crush, Toast, Cool", "Crush, Tear, Curl", "Cut, Twist, Cool"], "a": 2, "e": "CTC मशीन पत्तियों को crush, tear और curl कर दानेदार चाय बनाती है; orthodox विधि में rolling होती है।", "s": "FP", "lv": "Easy"}, {"q": "काली चाय निर्माण में तथाकथित 'किण्वन' (Fermentation) वास्तव में क्या है?\nIn black tea manufacture, the so-called 'fermentation' is actually:", "o": ["Yeast द्वारा alcohol बनना", "Polyphenol oxidase द्वारा catechins का ऑक्सीकरण (theaflavins, thearubigins बनना)", "Mould द्वारा अपघटन", "Lactic acid fermentation"], "a": 1, "e": "यह enzymatic oxidation है, सूक्ष्मजीवी किण्वन नहीं; theaflavins चमक व thearubigins रंग/गाढ़ापन देते हैं। Green tea में यह चरण नहीं होता।", "s": "FP", "lv": "Hard"}, {"q": "कॉफी के गीले प्रसंस्करण (Wet processing) में किण्वन का उद्देश्य क्या है?\nIn wet processing of coffee, fermentation is done to:", "o": ["Caffeine बढ़ाना", "बीज पर चिपके mucilage को हटाना", "बीज भूनना", "तेल निकालना"], "a": 1, "e": "Pulping के बाद बीज पर लगी चिपचिपी mucilage परत किण्वन से टूटकर धुल जाती है; इससे 'washed/parchment coffee' बनती है।", "s": "FP", "lv": "Moderate"}, {"q": "चॉकलेट में प्रयुक्त मुख्य वसा कौन-सी है?\nThe main fat used in chocolate is:", "o": ["Groundnut oil", "Palm olein", "Cocoa butter", "Ghee"], "a": 2, "e": "Cocoa butter कोको बीजों से मिलता है; इसका गलनांक मुँह के ताप के निकट होने से चॉकलेट मुँह में घुलती है।", "s": "FP", "lv": "Easy"}, {"q": "IQF का पूर्ण रूप क्या है?\nIQF stands for:", "o": ["Individual Quick Freezing", "Integrated Quality Factor", "Indian Quick Food", "Instant Quality Food"], "a": 0, "e": "IQF में मटर, फल के टुकड़े अलग-अलग तेज़ी से जमते हैं (fluidized bed freezer), छोटे बर्फ क्रिस्टल बनते हैं और गुणवत्ता बनी रहती है।", "s": "FP", "lv": "Easy"}, {"q": "सब्ज़ियों के ब्लांचिंग (Blanching) की पर्याप्तता जाँचने हेतु प्रायः किस एंजाइम का परीक्षण होता है?\nAdequacy of blanching of vegetables is usually checked by testing which enzyme?", "o": ["Invertase", "Peroxidase", "Amylase", "Lipase"], "a": 1, "e": "Peroxidase सबसे ताप-प्रतिरोधी एंजाइमों में है; इसके निष्क्रिय होने से माना जाता है कि अन्य एंजाइम भी निष्क्रिय हो गए।", "s": "FP", "lv": "Moderate"}, {"q": "UHT दूध को लंबे समय तक बिना फ्रिज सुरक्षित रखने हेतु किस पैकेजिंग के साथ जोड़ा जाता है?\nUHT milk is combined with which packaging to keep it shelf-stable without refrigeration?", "o": ["Modified atmosphere packaging", "Aseptic packaging", "Vacuum packaging", "Shrink packaging"], "a": 1, "e": "UHT (लगभग 135 - 150 °C, कुछ सेकंड) के बाद sterile पैक में sterile वातावरण में भरना aseptic packaging (जैसे Tetra Pak) है।", "s": "FP", "lv": "Moderate"}, {"q": "पशु वध के बाद मांसपेशियों के अकड़ने (Rigor mortis) का मुख्य कारण क्या है?\nThe main cause of rigor mortis after slaughter is:", "o": ["ATP की कमी से actin-myosin का स्थायी जुड़ना", "Water का बढ़ना", "Fat का जमना", "Glycogen का बढ़ना"], "a": 0, "e": "ATP समाप्त होने पर actomyosin complex टूट नहीं पाता और मांस कड़ा हो जाता है; बाद में proteolysis से मांस नरम (resolution) होता है।", "s": "FP", "lv": "Moderate"}, {"q": "मांस क्योरिंग (Curing) में सोडियम नाइट्राइट के दो मुख्य कार्य कौन-से हैं?\nWhat are the two main functions of sodium nitrite in meat curing?", "o": ["वसा घटाना व प्रोटीन बढ़ाना", "गुलाबी रंग (nitrosomyoglobin) देना व Clostridium botulinum को रोकना", "मिठास व नमी", "कोमलता व झाग"], "a": 1, "e": "Nitrite → nitric oxide → myoglobin से nitrosomyoglobin (गुलाबी); साथ ही botulinum spores के अंकुरण को रोकता है।", "s": "FP", "lv": "Moderate"}, {"q": "हैमर मिल (Hammer mill) में आकार घटाने (size reduction) का मुख्य बल कौन-सा है?\nThe main force used for size reduction in a hammer mill is:", "o": ["Impact", "Shear only", "Compression", "Cutting only"], "a": 0, "e": "घूमते hammers पदार्थ पर तेज़ प्रहार (impact) करते हैं; roller mill में compression/shear तथा cutter में cutting मुख्य होता है।", "s": "FP", "lv": "Moderate"}]}, {"id": "FSO02", "series": "bihar-fso", "title": "Bihar FSO Mock Test 02 - Full Length (FREE)", "dur": 120, "mpq": 1, "neg": 0.25, "free": true, "rel": "2026-11-14", "questions": [{"q": "नालंदा विश्वविद्यालय की स्थापना किसने की थी?\nWho founded Nalanda University?", "o": ["धर्मपाल / Dharmapala", "कुमारगुप्त प्रथम / Kumaragupta I", "अशोक / Ashoka", "हर्षवर्धन / Harshavardhana"], "a": 1, "e": "गुप्त शासक कुमारगुप्त प्रथम (5वीं सदी) ने नालंदा महाविहार की स्थापना की; ह्वेनसांग ने यहाँ अध्ययन किया।", "s": "GS", "lv": "Easy"}, {"q": "गौतम बुद्ध को ज्ञान (बोधि) कहाँ प्राप्त हुआ था?\nWhere did Gautama Buddha attain enlightenment?", "o": ["कुशीनगर / Kushinagar", "बोधगया / Bodh Gaya", "सारनाथ / Sarnath", "लुम्बिनी / Lumbini"], "a": 1, "e": "बोधगया (गया, बिहार) में पीपल (बोधि वृक्ष) के नीचे ज्ञान; सारनाथ में प्रथम उपदेश, कुशीनगर में महापरिनिर्वाण।", "s": "GS", "lv": "Easy"}, {"q": "भगवान महावीर का जन्म कहाँ हुआ था?\nWhere was Lord Mahavira born?", "o": ["राजगृह / Rajgriha", "पावापुरी / Pawapuri", "कुंडग्राम (वैशाली) / Kundagram", "श्रावस्ती / Shravasti"], "a": 2, "e": "महावीर का जन्म वैशाली के निकट कुंडग्राम में; निर्वाण पावापुरी (नालंदा) में हुआ।", "s": "GS", "lv": "Moderate"}, {"q": "शेरशाह सूरी का मकबरा कहाँ स्थित है?\nWhere is the tomb of Sher Shah Suri located?", "o": ["दिल्ली / Delhi", "आगरा / Agra", "सासाराम / Sasaram", "पटना / Patna"], "a": 2, "e": "सासाराम (रोहतास, बिहार) में झील के बीच बना अफगान स्थापत्य का मकबरा।", "s": "GS", "lv": "Easy"}, {"q": "डॉ. राजेंद्र प्रसाद का जन्म बिहार के किस स्थान पर हुआ था?\nWhere in Bihar was Dr. Rajendra Prasad born?", "o": ["छपरा / Chhapra", "मुज़फ़्फ़रपुर / Muzaffarpur", "जीरादेई (सीवान) / Ziradei", "आरा / Arrah"], "a": 2, "e": "भारत के पहले राष्ट्रपति डॉ. राजेंद्र प्रसाद का जन्म 1884 में जीरादेई, सीवान में हुआ।", "s": "GS", "lv": "Easy"}, {"q": "1857 के विद्रोह में बिहार (जगदीशपुर) से किसने नेतृत्व किया?\nWho led the Revolt of 1857 from Jagdishpur in Bihar?", "o": ["बाबू कुंवर सिंह", "तात्या टोपे", "नाना साहब", "मंगल पांडे"], "a": 0, "e": "जगदीशपुर (भोजपुर) के 80 वर्षीय बाबू कुंवर सिंह ने अंग्रेज़ों के विरुद्ध संघर्ष किया।", "s": "GS", "lv": "Easy"}, {"q": "पटना का शहीद स्मारक (सचिवालय के सामने) किस आंदोलन के शहीदों की स्मृति में है?\nThe Shaheed Smarak in front of Patna Secretariat commemorates martyrs of which movement?", "o": ["असहयोग आंदोलन 1920", "भारत छोड़ो आंदोलन 1942", "सविनय अवज्ञा 1930", "1857 का विद्रोह"], "a": 1, "e": "11 अगस्त 1942 को सचिवालय पर तिरंगा फहराते हुए सात छात्र शहीद हुए थे।", "s": "GS", "lv": "Moderate"}, {"q": "मौलिक कर्तव्य (Fundamental Duties) संविधान में किस संशोधन द्वारा जोड़े गए?\nFundamental Duties were added to the Constitution by which amendment?", "o": ["42वाँ (1976)", "52वाँ (1985)", "86वाँ (2002)", "44वाँ (1978)"], "a": 0, "e": "स्वर्ण सिंह समिति की सिफारिश पर 42वें संशोधन से भाग IV-A, अनुच्छेद 51A जोड़ा गया।", "s": "GS", "lv": "Moderate"}, {"q": "'खाद्य पदार्थों में मिलावट' (Adulteration of foodstuffs) विषय संविधान की किस सूची में है?\n'Adulteration of foodstuffs and other goods' is placed in which list of the Constitution?", "o": ["राज्य सूची / State List", "किसी सूची में नहीं", "समवर्ती सूची / Concurrent List", "संघ सूची / Union List"], "a": 2, "e": "सातवीं अनुसूची, समवर्ती सूची की प्रविष्टि 18; इसलिए केंद्र (FSS Act 2006) और राज्य दोनों कानून बना सकते हैं।", "s": "GS", "lv": "Hard"}, {"q": "किसी राज्य में राष्ट्रपति शासन किस अनुच्छेद के अंतर्गत लगाया जाता है?\nPresident's Rule in a state is imposed under which Article?", "o": ["अनुच्छेद 352", "अनुच्छेद 370", "अनुच्छेद 356", "अनुच्छेद 360"], "a": 2, "e": "356 - राज्य में संवैधानिक तंत्र विफल होने पर; 352 - राष्ट्रीय आपातकाल; 360 - वित्तीय आपातकाल।", "s": "GS", "lv": "Easy"}, {"q": "राज्य के राज्यपाल की नियुक्ति कौन करता है?\nWho appoints the Governor of a state?", "o": ["राष्ट्रपति", "मुख्यमंत्री", "प्रधानमंत्री", "उच्च न्यायालय के मुख्य न्यायाधीश"], "a": 0, "e": "अनुच्छेद 155 के अनुसार राष्ट्रपति राज्यपाल की नियुक्ति करते हैं।", "s": "GS", "lv": "Easy"}, {"q": "भारत में वस्तु एवं सेवा कर (GST) कब लागू हुआ?\nWhen was GST implemented in India?", "o": ["15 अगस्त 2017", "1 अप्रैल 2016", "1 जनवरी 2018", "1 जुलाई 2017"], "a": 3, "e": "101वें संविधान संशोधन के बाद 1 जुलाई 2017 से GST लागू हुआ।", "s": "GS", "lv": "Easy"}, {"q": "भारत में हरित क्रांति के जनक किसे माना जाता है?\nWho is regarded as the father of the Green Revolution in India?", "o": ["सी. सुब्रमण्यम", "नॉर्मन बोरलॉग", "एम. एस. स्वामीनाथन", "वर्गीज़ कुरियन"], "a": 2, "e": "M.S. Swaminathan भारत में हरित क्रांति के जनक; Norman Borlaug विश्व स्तर पर; Kurien श्वेत क्रांति के जनक।", "s": "GS", "lv": "Easy"}, {"q": "'ऑपरेशन फ्लड' (Operation Flood) किससे संबंधित है?\n'Operation Flood' is related to:", "o": ["दुग्ध उत्पादन", "बाढ़ नियंत्रण", "तिलहन उत्पादन", "मत्स्य उत्पादन"], "a": 0, "e": "1970 में NDDB द्वारा वर्गीज़ कुरियन के नेतृत्व में शुरू; भारत विश्व का सबसे बड़ा दूध उत्पादक बना।", "s": "GS", "lv": "Easy"}, {"q": "कर्क रेखा (Tropic of Cancer) निम्न में से किस राज्य से होकर नहीं गुजरती?\nThe Tropic of Cancer does NOT pass through which state?", "o": ["त्रिपुरा / Tripura", "मिज़ोरम / Mizoram", "झारखंड / Jharkhand", "बिहार / Bihar"], "a": 3, "e": "कर्क रेखा 8 राज्यों से गुजरती है: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा, मिज़ोरम; बिहार इसके उत्तर में है।", "s": "GS", "lv": "Moderate"}, {"q": "सोन नदी का उद्गम स्थल कहाँ है?\nWhere does the Son river originate?", "o": ["महाबलेश्वर / Mahabaleshwar", "छोटानागपुर पठार / Chota Nagpur", "अमरकंटक / Amarkantak", "गंगोत्री / Gangotri"], "a": 2, "e": "सोन नदी मध्य प्रदेश के अमरकंटक से निकलकर पटना के निकट गंगा में मिलती है; नर्मदा भी अमरकंटक से निकलती है।", "s": "GS", "lv": "Moderate"}, {"q": "गंगा के मैदान में नई जलोढ़ मिट्टी (new alluvium), जो हर वर्ष बाढ़ से जमा होती है, क्या कहलाती है?\nThe new alluvium deposited every year by floods in the Ganga plain is called:", "o": ["भाबर / Bhabar", "खादर / Khadar", "बांगर / Bhangar", "तराई / Terai"], "a": 1, "e": "खादर नई, उपजाऊ जलोढ़; बांगर पुरानी जलोढ़ (कंकड़ युक्त); भाबर-तराई हिमालय की तलहटी के क्षेत्र हैं।", "s": "GS", "lv": "Moderate"}, {"q": "बेकिंग सोडा (Baking soda) का रासायनिक नाम क्या है?\nWhat is the chemical name of baking soda?", "o": ["सोडियम क्लोराइड", "सोडियम बाइकार्बोनेट", "सोडियम कार्बोनेट", "कैल्शियम कार्बोनेट"], "a": 1, "e": "Baking soda = NaHCO₃; गर्म करने पर CO₂ देता है जिससे केक फूलता है। Washing soda = Na₂CO₃·10H₂O।", "s": "GS", "lv": "Easy"}, {"q": "विद्युत प्रतिरोध (Electrical resistance) का SI मात्रक क्या है?\nWhat is the SI unit of electrical resistance?", "o": ["वोल्ट / Volt", "वाट / Watt", "एम्पियर / Ampere", "ओम / Ohm"], "a": 3, "e": "Ohm के नियम V = IR से प्रतिरोध का मात्रक ओम (Ω) है।", "s": "GS", "lv": "Easy"}, {"q": "विश्व खाद्य सुरक्षा दिवस (World Food Safety Day) कब मनाया जाता है?\nWhen is World Food Safety Day observed?", "o": ["16 अक्टूबर", "7 अप्रैल", "5 जून", "7 जून"], "a": 3, "e": "7 जून - World Food Safety Day (UN, 2019 से); 16 अक्टूबर - World Food Day (FAO स्थापना); 5 जून - पर्यावरण दिवस।", "s": "GS", "lv": "Easy"}, {"q": "भूकंप की तीव्रता (Intensity) किस पैमाने पर मापी जाती है?\nThe intensity of an earthquake is measured on which scale?", "o": ["रिक्टर स्केल / Richter", "ब्यूफोर्ट स्केल / Beaufort", "pH स्केल", "मरकैली स्केल / Mercalli"], "a": 3, "e": "Intensity (नुकसान/प्रभाव) - Modified Mercalli scale; Magnitude (ऊर्जा) - Richter/moment magnitude scale।", "s": "GS", "lv": "Moderate"}, {"q": "विषम शब्द चुनिए: Casein, Gluten, Zein, Starch\nChoose the odd one: Casein, Gluten, Zein, Starch", "o": ["Casein", "Starch", "Gluten", "Zein"], "a": 1, "e": "Casein (दूध), Gluten (गेहूँ), Zein (मक्का) प्रोटीन हैं; Starch कार्बोहाइड्रेट है।", "s": "MA", "lv": "Easy"}, {"q": "श्रृंखला पूरी कीजिए: 2, 6, 12, 20, 30, ?\nComplete the series: 2, 6, 12, 20, 30, ?", "o": ["44", "48", "40", "42"], "a": 3, "e": "अंतर 4, 6, 8, 10, 12; अतः 30 + 12 = 42 (n × (n+1) पैटर्न)।", "s": "MA", "lv": "Easy"}, {"q": "आँकड़ों 2, 4, 6, 8 का प्रसरण (Population variance, σ²) कितना है?\nWhat is the population variance (σ²) of 2, 4, 6, 8?", "o": ["5", "20", "4", "6"], "a": 0, "e": "Mean = 5; विचलन के वर्ग 9, 1, 1, 9 = 20; σ² = 20 ÷ 4 = 5।", "s": "MA", "lv": "Moderate"}, {"q": "एक व्यक्ति 4 km उत्तर चलकर दाएँ मुड़ता है और 3 km चलता है। वह आरंभ बिंदु से कितनी दूर है?\nA man walks 4 km north, turns right and walks 3 km. How far is he from the start?", "o": ["5 km", "6 km", "7 km", "1 km"], "a": 0, "e": "समकोण त्रिभुज: √(4² + 3²) = √25 = 5 km (उत्तर-पूर्व दिशा में)।", "s": "MA", "lv": "Easy"}, {"q": "सेलुलोज़ (Cellulose) में ग्लूकोज़ इकाइयाँ किस बंध से जुड़ी होती हैं?\nGlucose units in cellulose are joined by:", "o": ["α-1,4", "β-1,4", "α-1,6", "β-1,2"], "a": 1, "e": "β-1,4 बंध को मानव पाचक एंजाइम नहीं तोड़ पाते, इसलिए cellulose dietary fibre है।", "s": "FC", "lv": "Easy"}, {"q": "आयोडीन विलयन के साथ एमाइलोज़ (Amylose) कौन-सा रंग देता है?\nWhat colour does amylose give with iodine solution?", "o": ["पीला / Yellow", "हरा / Green", "लाल-भूरा / Red-brown", "गहरा नीला / Deep blue"], "a": 3, "e": "Amylose की helix में iodine फँसकर गहरा नीला; amylopectin लाल-बैंगनी तथा glycogen लाल-भूरा रंग देता है।", "s": "FC", "lv": "Easy"}, {"q": "निम्न में से कौन-सा घुलनशील आहारीय रेशा (soluble dietary fibre) है?\nWhich of the following is a soluble dietary fibre?", "o": ["Cellulose", "Lignin", "Hemicellulose (अघुलनशील भाग)", "β-glucan (जई)"], "a": 3, "e": "Oats/barley का β-glucan, pectin, gums घुलनशील रेशे हैं जो कोलेस्ट्रॉल घटाते हैं; cellulose, lignin अघुलनशील हैं।", "s": "FC", "lv": "Moderate"}, {"q": "इनवर्ट शुगर (Invert sugar) क्या है?\nWhat is invert sugar?", "o": ["Sucrose के जल-अपघटन से बना glucose व fructose का समान मिश्रण", "केवल glucose", "Maltose व glucose का मिश्रण", "Lactose का रूप"], "a": 0, "e": "Invertase या अम्ल से sucrose टूटकर glucose + fructose बनते हैं; ध्रुवण कोण (+ से -) उलटने के कारण नाम 'invert'। यह क्रिस्टलीकरण रोकती है।", "s": "FC", "lv": "Moderate"}, {"q": "प्राकृतिक शर्कराओं में सबसे अधिक मीठी कौन-सी है?\nWhich is the sweetest natural sugar?", "o": ["Glucose", "Lactose", "Fructose", "Sucrose"], "a": 2, "e": "सापेक्ष मिठास: fructose (~1.7) > sucrose (1.0) > glucose (~0.7) > lactose (~0.2)।", "s": "FC", "lv": "Easy"}, {"q": "स्टार्च को सूखी ऊष्मा देने (जैसे ब्रेड टोस्ट करना) पर डेक्सट्रिन बनने की क्रिया क्या कहलाती है?\nFormation of dextrins on dry heating of starch (as in toasting bread) is called:", "o": ["Retrogradation", "Gelatinization", "Syneresis", "Dextrinization"], "a": 3, "e": "सूखी ऊष्मा से starch छोटे अणुओं (dextrins) में टूटता है, हल्का भूरा रंग व स्वाद आता है।", "s": "FC", "lv": "Moderate"}, {"q": "प्रोटीन की α-हेलिक्स (alpha helix) संरचना किस स्तर की संरचना है?\nThe α-helix of a protein is which level of structure?", "o": ["Tertiary", "Secondary", "Quaternary", "Primary"], "a": 1, "e": "Secondary structure (α-helix, β-sheet) hydrogen bonds से बनती है; primary = amino acid क्रम।", "s": "FC", "lv": "Easy"}, {"q": "पेप्टाइड बंध (Peptide bond) किनके बीच बनता है?\nA peptide bond is formed between:", "o": ["दो carboxyl groups", "दो amino groups", "एक amino acid के carboxyl व दूसरे के amino group", "Fatty acid व glycerol"], "a": 2, "e": "–COOH व –NH₂ के बीच जल निकलकर (condensation) –CO–NH– बंध बनता है।", "s": "FC", "lv": "Easy"}, {"q": "कच्चे अंडे की सफ़ेदी का कौन-सा प्रोटीन बायोटिन (biotin) से बंधकर उसकी कमी कर सकता है?\nWhich raw egg-white protein binds biotin and can cause its deficiency?", "o": ["Lysozyme", "Conalbumin", "Avidin", "Ovalbumin"], "a": 2, "e": "Avidin biotin को बाँध लेता है; पकाने पर avidin विकृत होकर निष्क्रिय हो जाता है।", "s": "FC", "lv": "Moderate"}, {"q": "निम्न में से किस खाद्य प्रोटीन का जैविक मान (Biological value) सबसे अधिक है और इसे संदर्भ प्रोटीन माना जाता है?\nWhich food protein has the highest biological value and is taken as reference protein?", "o": ["मक्का प्रोटीन", "गेहूँ प्रोटीन", "चना प्रोटीन", "अंडा प्रोटीन"], "a": 3, "e": "Whole egg protein का BV लगभग 94 - 100 है, सभी आवश्यक amino acids संतुलित मात्रा में।", "s": "FC", "lv": "Moderate"}, {"q": "किजेल्डाल विधि (Kjeldahl method) से सामान्यतः प्रोटीन ज्ञात करने के लिए नाइट्रोजन को किस गुणांक से गुणा करते हैं?\nIn the Kjeldahl method, nitrogen is generally multiplied by which factor to estimate protein?", "o": ["5.70", "6.25", "9.00", "4.18"], "a": 1, "e": "अधिकांश प्रोटीन में ~16% N होता है, 100/16 = 6.25। गेहूँ के लिए 5.70 और दूध के लिए 6.38 प्रयोग होता है।", "s": "FC", "lv": "Moderate"}, {"q": "दूध प्रोटीन के लिए नाइट्रोजन-से-प्रोटीन रूपांतरण गुणांक कितना है?\nThe nitrogen-to-protein conversion factor for milk protein is:", "o": ["6.38", "5.70", "6.25", "5.30"], "a": 0, "e": "दूध प्रोटीन में ~15.7% N होने से गुणांक 6.38 लिया जाता है।", "s": "FC", "lv": "Hard"}, {"q": "निम्न में से कौन-सा आवश्यक वसीय अम्ल (Essential fatty acid) है?\nWhich of the following is an essential fatty acid?", "o": ["Stearic acid", "Oleic acid", "Palmitic acid", "Linoleic acid"], "a": 3, "e": "Linoleic (ω-6) व α-linolenic (ω-3) शरीर नहीं बना सकता; palmitic, stearic संतृप्त तथा oleic MUFA है।", "s": "FC", "lv": "Easy"}, {"q": "ओमेगा-3 वसीय अम्ल α-लिनोलेनिक अम्ल (ALA) का अच्छा वनस्पति स्रोत कौन-सा है?\nA good plant source of the omega-3 fatty acid α-linolenic acid (ALA) is:", "o": ["नारियल तेल", "पाम तेल", "घी", "अलसी / Flaxseed"], "a": 3, "e": "अलसी (Linum) में ALA सर्वाधिक; नारियल व पाम तेल में संतृप्त वसा अधिक होती है।", "s": "FC", "lv": "Moderate"}, {"q": "तेल का पेरॉक्साइड मान (Peroxide value) क्या मापता है?\nThe peroxide value of an oil measures:", "o": ["असंतृप्तता", "Primary oxidation products (hydroperoxides)", "Free fatty acids", "Secondary oxidation products (aldehydes)"], "a": 1, "e": "PV ऑक्सीकरण की प्रारंभिक अवस्था के hydroperoxides बताता है (meq O₂/kg); secondary products anisidine/TBA मान से मापे जाते हैं।", "s": "FC", "lv": "Moderate"}, {"q": "घी में मिलावट जाँचने के लिए प्रयुक्त राइकर्ट-माइसल मान (Reichert-Meissl value) क्या दर्शाता है?\nThe Reichert-Meissl value, used to detect ghee adulteration, indicates:", "o": ["असंतृप्त वसीय अम्ल", "जल में अघुलनशील वसीय अम्ल", "वाष्पशील, जल में घुलनशील वसीय अम्ल (मुख्यतः butyric)", "Peroxides"], "a": 2, "e": "शुद्ध घी में butyric आदि वाष्पशील घुलनशील fatty acids अधिक होने से RM value अधिक; वनस्पति मिलाने पर यह घट जाता है। Polenske value वाष्पशील अघुलनशील अम्ल बताता है।", "s": "FC", "lv": "Hard"}, {"q": "निम्न में से कौन तेल के ऑक्सीकरण (oxidative rancidity) को तेज़ करता है (pro-oxidant)?\nWhich of the following accelerates oxidative rancidity (pro-oxidant)?", "o": ["Tocopherol", "अंधेरे व ठंडे में भंडारण", "Citric acid", "ताँबा व लोहा जैसे धातु आयन"], "a": 3, "e": "Cu, Fe आयन, प्रकाश व ऊष्मा free radical निर्माण बढ़ाते हैं; citric acid धातुओं को chelate करके synergist का काम करता है।", "s": "FC", "lv": "Moderate"}, {"q": "वसा का स्वतः-ऑक्सीकरण (Autoxidation) किस क्रियाविधि से होता है?\nAutoxidation of fats proceeds by which mechanism?", "o": ["Fermentation", "Enzymatic hydrolysis", "Ionic substitution", "Free radical chain reaction (initiation - propagation - termination)"], "a": 3, "e": "असंतृप्त fatty acid से H हटकर free radical बनता है, O₂ से peroxy radical बनकर श्रृंखला चलती है; antioxidants radicals को रोकते हैं।", "s": "FC", "lv": "Moderate"}, {"q": "क्लोरोफिल अणु के केंद्र में कौन-सा धातु आयन होता है?\nWhich metal ion is present at the centre of the chlorophyll molecule?", "o": ["Copper", "Iron", "Magnesium", "Zinc"], "a": 2, "e": "Chlorophyll porphyrin वलय के केंद्र में Mg²⁺; heme (हीमोग्लोबिन/मायोग्लोबिन) में Fe²⁺ होता है।", "s": "FC", "lv": "Easy"}, {"q": "कौन-सा कैरोटिनॉयड प्रो-विटामिन A (Provitamin A) के रूप में सर्वाधिक सक्रिय है?\nWhich carotenoid is most active as provitamin A?", "o": ["β-Carotene", "Capsanthin", "Lutein", "Lycopene"], "a": 0, "e": "β-carotene टूटकर retinol (विटामिन A) बनाता है; lycopene में β-ionone वलय नहीं होने से provitamin A सक्रियता नहीं होती।", "s": "FC", "lv": "Easy"}, {"q": "ताज़े कटे मांस को हवा में रखने पर चमकीला लाल रंग और बाद में भूरा रंग किन रूपों के कारण होता है?\nFreshly cut meat turns bright red in air and later brown. These colours are due to:", "o": ["Metmyoglobin (लाल) व Nitrosomyoglobin (भूरा)", "Oxymyoglobin (चमकीला लाल) व Metmyoglobin, Fe³⁺ (भूरा)", "Hemoglobin व Chlorophyll", "Myoglobin (लाल) व Oxymyoglobin (भूरा)"], "a": 1, "e": "Myoglobin (बैंगनी-लाल) O₂ से oxymyoglobin (चमकीला लाल) बनता है; Fe²⁺ के Fe³⁺ में ऑक्सीकरण से metmyoglobin (भूरा) बनता है।", "s": "FC", "lv": "Hard"}, {"q": "लहसुन की विशिष्ट गंध देने वाला एलिसिन (Allicin) कैसे बनता है?\nHow is allicin, responsible for garlic odour, formed?", "o": ["सुखाने पर Maillard से", "कूटने/काटने पर alliinase एंजाइम द्वारा alliin से", "किण्वन से", "पकाने पर स्टार्च से"], "a": 1, "e": "साबुत लहसुन में alliin व alliinase अलग रहते हैं; कोशिका टूटने पर एंजाइम क्रिया से allicin बनता है।", "s": "FC", "lv": "Moderate"}, {"q": "प्याज़ काटने पर आँसू लाने वाला यौगिक (lachrymatory factor) कौन-सा है?\nWhich compound is the tear-inducing (lachrymatory) factor of onion?", "o": ["Allicin", "Capsaicin", "syn-Propanethial-S-oxide", "Diallyl disulphide"], "a": 2, "e": "प्याज़ में alliinase व LF-synthase से syn-propanethial-S-oxide बनता है जो आँखों में जलन करता है।", "s": "FC", "lv": "Hard"}, {"q": "'उमामी' (Umami) स्वाद मुख्यतः किस यौगिक से जुड़ा है?\n'Umami' taste is mainly associated with:", "o": ["Caffeine", "Sodium chloride", "Monosodium glutamate (MSG)", "Citric acid"], "a": 2, "e": "Glutamate व 5'-nucleotides (IMP, GMP) उमामी (savoury) स्वाद देते हैं; यह पाँचवाँ मूल स्वाद है।", "s": "FC", "lv": "Easy"}, {"q": "निम्न में से कौन-सा उपाय एंजाइमी भूरापन (enzymatic browning) को नहीं रोकता?\nWhich of the following does NOT prevent enzymatic browning?", "o": ["Sulphite उपचार", "ताँबे के बर्तन में कटे फल रखना", "Ascorbic acid मिलाना", "Blanching"], "a": 1, "e": "PPO copper-dependent है, ताँबा भूरापन बढ़ा सकता है; ascorbic acid quinones को अपचयित करता है, blanching एंजाइम नष्ट करता है, sulphites PPO को रोकते हैं।", "s": "FC", "lv": "Moderate"}, {"q": "यीस्ट (Yeast) में सामान्य अलैंगिक प्रजनन किस विधि से होता है?\nYeast commonly reproduces asexually by:", "o": ["Binary fission", "Fragmentation", "Budding", "Conidia"], "a": 2, "e": "Saccharomyces मुकुलन (budding) से बढ़ता है; जीवाणु binary fission से तथा मोल्ड conidia/sporangiospores से।", "s": "FM", "lv": "Easy"}, {"q": "मोल्ड (Mould) के कवक तंतुओं (hyphae) के समूह को क्या कहते हैं?\nThe mass of hyphae of a mould is called:", "o": ["Capsule", "Spore", "Colony", "Mycelium"], "a": 3, "e": "Hyphae का जाल mycelium कहलाता है; खाद्य पर दिखने वाली रोएँदार परत यही है।", "s": "FM", "lv": "Easy"}, {"q": "निम्न में से कौन-सा कारक सूक्ष्मजीव वृद्धि का बाह्य कारक (extrinsic factor) है?\nWhich of the following is an extrinsic factor of microbial growth?", "o": ["खाद्य का pH", "जल सक्रियता (aw)", "पोषक तत्व", "भंडारण ताप"], "a": 3, "e": "Intrinsic (खाद्य के भीतर): pH, aw, Eh, पोषक तत्व, प्राकृतिक antimicrobials; Extrinsic: ताप, सापेक्ष आर्द्रता, गैसें।", "s": "FM", "lv": "Moderate"}, {"q": "अंडे की सफ़ेदी में प्राकृतिक रूप से उपस्थित कौन-सा एंजाइम जीवाणु की कोशिका भित्ति तोड़ता है?\nWhich naturally occurring enzyme in egg white lyses bacterial cell walls?", "o": ["Invertase", "Lysozyme", "Lipase", "Amylase"], "a": 1, "e": "Lysozyme peptidoglycan को तोड़ता है (विशेषकर Gram positive); यह intrinsic antimicrobial constituent का उदाहरण है।", "s": "FM", "lv": "Moderate"}, {"q": "डिब्बाबंद खाद्य में 'फ्लैट सॉर' (Flat sour) खराबी किस जीवाणु से होती है?\n'Flat sour' spoilage of canned foods is caused by:", "o": ["Clostridium botulinum", "Lactobacillus brevis", "Escherichia coli", "Geobacillus stearothermophilus"], "a": 3, "e": "यह thermophilic spore-former अम्ल तो बनाता है पर गैस नहीं, इसलिए डिब्बा फूलता नहीं (flat) पर खाद्य खट्टा हो जाता है।", "s": "FM", "lv": "Hard"}, {"q": "तापीय प्रसंस्करण में z-value का अर्थ क्या है?\nIn thermal processing, the z-value is:", "o": ["D-value को 10 गुना (1 log) बदलने के लिए आवश्यक ताप परिवर्तन", "121 °C पर कुल समय", "90% सूक्ष्मजीव मारने का समय", "सूक्ष्मजीवों की प्रारंभिक संख्या"], "a": 0, "e": "z-value सूक्ष्मजीव की ताप संवेदनशीलता बताता है; C. botulinum के लिए सामान्यतः 10 °C लिया जाता है।", "s": "FM", "lv": "Moderate"}, {"q": "कम-अम्लीय डिब्बाबंद खाद्य में 'बोटुलिनम कुक' (12-D concept) का अर्थ क्या है?\nIn low-acid canned foods, the 'botulinum cook' (12-D concept) means:", "o": ["12 मिनट तक उबालना", "12 °C पर भंडारण", "12 बार धोना", "C. botulinum spores की संख्या को 10¹² गुना घटाना"], "a": 3, "e": "प्रोसेस इतना दिया जाता है कि spores की संख्या 12 log cycles घटे; व्यवहार में 121.1 °C पर लगभग 2.5 - 3 मिनट (F₀) के बराबर।", "s": "FM", "lv": "Moderate"}, {"q": "F₀ मान (F₀ value) किस संदर्भ ताप पर व्यक्त किया जाता है?\nThe F₀ value is expressed at which reference temperature?", "o": ["110 °C", "135 °C", "100 °C", "121.1 °C (250 °F)"], "a": 3, "e": "F₀ = 121.1 °C पर z = 10 °C मानकर दिया गया समतुल्य sterilization समय (मिनट)।", "s": "FM", "lv": "Moderate"}, {"q": "कौन-सा खाद्य-जनित जीवाणु संक्रमण के बाद 'गिलियन-बैरे सिंड्रोम' (Guillain-Barré syndrome) से जुड़ा है?\nWhich foodborne bacterium is linked to Guillain-Barré syndrome after infection?", "o": ["Staphylococcus aureus", "Clostridium perfringens", "Campylobacter jejuni", "Bacillus cereus"], "a": 2, "e": "C. jejuni (अधपकी पोल्ट्री, कच्चा दूध) बैक्टीरियल दस्त का प्रमुख कारण है और कभी-कभी GBS (तंत्रिका पक्षाघात) करता है।", "s": "FM", "lv": "Hard"}, {"q": "Vibrio parahaemolyticus खाद्य विषाक्तता मुख्यतः किस खाद्य से जुड़ी है?\nVibrio parahaemolyticus food poisoning is mainly associated with:", "o": ["समुद्री भोजन (seafood)", "दूध उत्पाद", "डिब्बाबंद सब्ज़ियाँ", "अनाज"], "a": 0, "e": "यह halophilic (लवण-प्रिय) जीवाणु है; कच्ची/अधपकी समुद्री मछली व शेलफिश से फैलता है।", "s": "FM", "lv": "Moderate"}, {"q": "निम्न में से कौन-सा खाद्य व जल से फैलने वाला विषाणु रोग है?\nWhich of the following is a viral disease spread through food and water?", "o": ["Cholera", "Typhoid", "Botulism", "Hepatitis A"], "a": 3, "e": "Hepatitis A विषाणु faecal-oral मार्ग से फैलता है; typhoid (Salmonella Typhi), cholera (Vibrio cholerae) जीवाणु रोग हैं।", "s": "FM", "lv": "Easy"}, {"q": "विश्व में विषाणु-जनित तीव्र आंत्रशोथ (viral gastroenteritis) का सबसे सामान्य कारण कौन-सा है?\nThe most common cause of viral gastroenteritis worldwide is:", "o": ["Hepatitis E", "Norovirus", "Influenza virus", "Rotavirus (केवल वयस्क)"], "a": 1, "e": "Norovirus अत्यधिक संक्रामक है (कम संख्या में भी), भोजन संभालने वालों, शेलफिश, क्रूज़ जहाज़ों पर प्रकोप सामान्य।", "s": "FM", "lv": "Moderate"}, {"q": "बड़ी मात्रा में पकाकर धीरे-धीरे ठंडा किए गए मांस/दाल व्यंजनों से होने वाली खाद्य विषाक्तता प्रायः किस जीवाणु से होती है?\nFood poisoning from large quantities of meat/gravy dishes cooled slowly is often due to:", "o": ["Shigella sonnei", "Listeria monocytogenes", "Vibrio cholerae", "Clostridium perfringens"], "a": 3, "e": "C. perfringens के spores पकाने में बच जाते हैं और धीमी ठंडक में तेज़ी से बढ़ते हैं (generation time ~10 मिनट); 'cafeteria germ'।", "s": "FM", "lv": "Moderate"}, {"q": "निम्न में से कौन-सा खाद्य-जनित रोग 'विषाक्तता' (intoxication) है, संक्रमण नहीं?\nWhich of the following foodborne illnesses is an intoxication rather than an infection?", "o": ["Shigellosis", "Salmonellosis", "Listeriosis", "Botulism"], "a": 3, "e": "Intoxication में खाद्य में पहले से बना विष रोग करता है (botulism, staphylococcal poisoning); infection में जीवित जीवाणु शरीर में बढ़ते हैं।", "s": "FM", "lv": "Moderate"}, {"q": "अर्गटिज़्म (Ergotism) किस कवक से संदूषित अनाज खाने से होता है?\nErgotism is caused by eating grains contaminated with:", "o": ["Fusarium graminearum", "Penicillium citrinum", "Aspergillus flavus", "Claviceps purpurea"], "a": 3, "e": "Claviceps (राई, बाजरा) के sclerotia में ergot alkaloids होते हैं, जिनसे gangrene व ऐंठन होती है।", "s": "FM", "lv": "Moderate"}, {"q": "खेसारी दाल (Lathyrus sativus) के अधिक सेवन से होने वाला लैथिरिज़्म (Lathyrism) किस विष से होता है?\nLathyrism from excessive consumption of khesari dal is caused by:", "o": ["BOAA (β-ODAP)", "Solanine", "Aflatoxin", "Gossypol"], "a": 0, "e": "BOAA/β-ODAP neurotoxin है, जिससे निचले अंगों का पक्षाघात (neurolathyrism) होता है; यह प्राकृतिक मूल का hazard है।", "s": "FM", "lv": "Moderate"}, {"q": "कड़वे बादाम व कसावा (Cassava) में पाए जाने वाले सायनोजेनिक ग्लाइकोसाइड (cyanogenic glycosides) से कौन-सा विषैला यौगिक मुक्त होता है?\nCyanogenic glycosides in bitter almond and cassava release which toxic compound?", "o": ["Hydrogen cyanide (HCN)", "Nitrite", "Histamine", "Oxalic acid"], "a": 0, "e": "Amygdalin (बादाम) व linamarin (कसावा) एंजाइम क्रिया से HCN देते हैं; भिगोना, सुखाना, पकाना इसे कम करता है।", "s": "FM", "lv": "Moderate"}, {"q": "बिनौला (Cottonseed) में पाया जाने वाला विषैला पॉलीफिनॉलिक वर्णक कौन-सा है?\nWhich toxic polyphenolic pigment is found in cottonseed?", "o": ["Solanine", "Curcumin", "Gossypol", "Tomatine"], "a": 2, "e": "Gossypol प्रोटीन की उपलब्धता घटाता है व विषैला है; refining/processing से हटाया जाता है।", "s": "FM", "lv": "Moderate"}, {"q": "हरे पड़ चुके या अंकुरित आलू में कौन-सा विषैला ग्लाइकोएल्कलॉइड (glycoalkaloid) अधिक होता है?\nWhich toxic glycoalkaloid is high in greened or sprouted potatoes?", "o": ["Nicotine", "Caffeine", "Solanine", "Capsaicin"], "a": 2, "e": "प्रकाश में आलू हरा होता है और solanine बढ़ता है; हरा भाग व अंकुर हटाकर ही प्रयोग करें।", "s": "FM", "lv": "Easy"}, {"q": "समुद्री मछली के खराब होने का रासायनिक सूचक ट्राइमिथाइलअमीन (TMA) किससे बनता है?\nTrimethylamine (TMA), an indicator of marine fish spoilage, is formed from:", "o": ["Trimethylamine oxide (TMAO) का जीवाणु द्वारा अपचयन", "Histidine", "Glycogen", "Lipids"], "a": 0, "e": "Shewanella putrefaciens जैसे जीवाणु TMAO को TMA में बदलते हैं, जिससे 'मछली जैसी' दुर्गंध आती है।", "s": "FM", "lv": "Moderate"}, {"q": "मांस की अवायवीय (anaerobic) सड़न, जिसमें H₂S, अमीन व दुर्गंध बनती है, क्या कहलाती है?\nAnaerobic spoilage of meat producing H₂S, amines and foul odour is called:", "o": ["Souring", "Mould growth", "Putrefaction", "Rancidity"], "a": 2, "e": "Clostridium आदि प्रोटीन को तोड़कर putrescine, cadaverine, H₂S बनाते हैं, यही putrefaction है।", "s": "FM", "lv": "Moderate"}, {"q": "सोडियम बेंज़ोएट (Sodium benzoate) परिरक्षक किस स्थिति में सबसे प्रभावी होता है?\nSodium benzoate is most effective as a preservative in:", "o": ["अम्लीय खाद्य (pH लगभग 4.5 से कम)", "केवल सूखे अनाज में", "क्षारीय खाद्य (pH > 8)", "उदासीन pH वाले मांस में"], "a": 0, "e": "अविघटित (undissociated) benzoic acid ही रोगाणुरोधी है, जो कम pH पर अधिक होता है; इसलिए स्क्वैश, अचार, सॉस में प्रयोग।", "s": "FM", "lv": "Moderate"}, {"q": "निसिन (Nisin), जो एक बैक्टीरियोसिन है, किस जीवाणु से प्राप्त होता है?\nNisin, a bacteriocin, is obtained from:", "o": ["Bacillus subtilis", "Lactococcus lactis", "Streptomyces griseus", "Escherichia coli"], "a": 1, "e": "Nisin Gram positive जीवाणुओं व spores पर प्रभावी प्राकृतिक परिरक्षक है; चीज़ व डिब्बाबंद उत्पादों में प्रयोग।", "s": "FM", "lv": "Moderate"}, {"q": "विकिरणित खाद्य (Irradiated food) के पैक पर लगने वाले अंतरराष्ट्रीय चिह्न को क्या कहते हैं?\nThe international symbol on packs of irradiated food is called:", "o": ["Agmark", "Radura", "Ecomark", "Codex"], "a": 1, "e": "Radura (हरा, पौधे जैसा चिह्न) विकिरणित खाद्य की पहचान है; विकिरण की मात्रा Gray (Gy) में मापी जाती है।", "s": "FM", "lv": "Moderate"}, {"q": "आधुनिक दूध पाश्चुरीकरण के ताप-समय मानक (जैसे 72 °C, 15 सेकंड) किस रोगजनक के विनाश पर आधारित हैं?\nModern milk pasteurization standards (e.g. 72 °C, 15 s) are based on destruction of:", "o": ["Coxiella burnetii", "Mycobacterium tuberculosis", "Clostridium botulinum spores", "Bacillus cereus spores"], "a": 0, "e": "Coxiella burnetii (Q fever) M. tuberculosis से अधिक ताप-प्रतिरोधी non-spore रोगजनक है, इसलिए मानक इसी पर आधारित है। Spores पाश्चुरीकरण में नहीं मरते।", "s": "FM", "lv": "Hard"}, {"q": "धान (Paddy) में भूसी (husk) का अंश लगभग कितना होता है?\nHusk constitutes about what proportion of paddy?", "o": ["10%", "40%", "5%", "20%"], "a": 3, "e": "धान में लगभग 20% husk, ~8 - 10% bran व germ, शेष endosperm (milled rice ~65 - 70%) होता है।", "s": "FP", "lv": "Moderate"}, {"q": "चावल मिलिंग में 'हेड राइस' (Head rice) किसे कहते हैं?\nIn rice milling, 'head rice' refers to:", "o": ["पूरी लंबाई के कम से कम 3/4 भाग वाले दाने", "केवल टूटे दाने", "चोकर सहित चावल", "उबला चावल"], "a": 0, "e": "Head rice yield मिलिंग गुणवत्ता का मुख्य सूचक है; parboiling से head rice बढ़ता है।", "s": "FP", "lv": "Hard"}, {"q": "ब्रेड बनाने के लिए किस प्रकार का गेहूँ का आटा सर्वाधिक उपयुक्त है?\nWhich type of wheat flour is most suitable for bread making?", "o": ["चावल का आटा", "कम प्रोटीन वाला soft wheat आटा", "मक्के का आटा", "अधिक प्रोटीन व मज़बूत ग्लूटेन वाला hard wheat आटा"], "a": 3, "e": "Strong gluten CO₂ रोककर loaf volume बढ़ाता है; soft wheat का कम प्रोटीन वाला आटा बिस्किट/केक के लिए उपयुक्त है।", "s": "FP", "lv": "Moderate"}, {"q": "पास्ता/मैकरोनी बनाने में प्रयुक्त सूजी (Semolina) मुख्यतः किस गेहूँ से बनती है?\nSemolina used for pasta/macaroni is mainly made from:", "o": ["जौ", "Triticum aestivum (bread wheat)", "Triticum durum (durum wheat)", "Triticum dicoccum"], "a": 2, "e": "Durum wheat कठोर, अधिक प्रोटीन व पीले रंग (carotenoids) वाला होता है, pasta के लिए आदर्श।", "s": "FP", "lv": "Moderate"}, {"q": "बीयर बनाने (Brewing) में हॉप्स (Hops) मिलाने का मुख्य उद्देश्य क्या है?\nThe main purpose of adding hops in brewing is:", "o": ["कड़वाहट व सुगंध देना (α-acids) तथा परिरक्षक प्रभाव", "Alcohol बढ़ाना", "रंग हल्का करना", "मिठास बढ़ाना"], "a": 0, "e": "Hops के α-acids उबालने पर iso-α-acids बनकर कड़वाहट देते हैं और कुछ जीवाणुरोधी प्रभाव भी रखते हैं।", "s": "FP", "lv": "Moderate"}, {"q": "बीयर व ब्रेड में किण्वन हेतु प्रयुक्त यीस्ट कौन-सा है?\nWhich yeast is used for fermentation in beer and bread?", "o": ["Aspergillus oryzae", "Candida albicans", "Saccharomyces cerevisiae", "Rhizopus oryzae"], "a": 2, "e": "S. cerevisiae शर्करा को ethanol व CO₂ में बदलता है; lager के लिए S. pastorianus प्रयोग होता है।", "s": "FP", "lv": "Moderate"}, {"q": "मक्के की सूखी मिलिंग (Dry milling) का मुख्य उत्पाद कौन-सा है?\nThe main product of dry milling of maize is:", "o": ["Starch", "Grits", "Gluten meal", "Glucose syrup"], "a": 1, "e": "Dry milling में degermination के बाद grits, meal, flour मिलते हैं; starch wet milling से।", "s": "FP", "lv": "Easy"}, {"q": "तिलहन से तेल निकालने के बाद बचे ठोस पदार्थ को क्या कहते हैं?\nThe solid residue left after oil extraction from oilseeds is called:", "o": ["Husk", "Bran", "Pomace", "Oil cake / Meal"], "a": 3, "e": "Expeller से oil cake तथा solvent extraction से de-oiled meal मिलता है; यह पशु आहार व प्रोटीन स्रोत है।", "s": "FP", "lv": "Easy"}, {"q": "तेल का शीतकरण (Winterization) क्यों किया जाता है?\nWhy is winterization of oil done?", "o": ["रंग हटाने हेतु", "गंध हटाने हेतु", "ठंड में धुंधलापन रोकने के लिए उच्च गलनांक वाले glycerides व waxes को ठंडा करके अलग करना", "Free fatty acids हटाने हेतु"], "a": 2, "e": "तेल को ठंडा कर ठोस हुए saturated glycerides/waxes छान दिए जाते हैं (जैसे cottonseed, sunflower salad oil), ताकि फ्रिज में तेल साफ़ रहे।", "s": "FP", "lv": "Hard"}, {"q": "दालों व अनाज के अंकुरण (Germination) का मुख्य पोषण लाभ क्या है?\nThe main nutritional benefit of germination of pulses and cereals is:", "o": ["विटामिन C बढ़ना व प्रति-पोषक तत्व (phytate, trypsin inhibitor) घटना", "Phytate बढ़ना", "Starch बढ़ना", "Protein नष्ट होना"], "a": 0, "e": "अंकुरण में एंजाइम सक्रिय होकर phytate तोड़ते हैं, खनिज उपलब्धता बढ़ती है और vitamin C व B समूह बढ़ते हैं।", "s": "FP", "lv": "Moderate"}, {"q": "इडली/डोसा घोल के किण्वन में प्रमुख जीवाणु कौन-सा है?\nWhich bacterium mainly ferments idli/dosa batter?", "o": ["Clostridium butyricum", "Streptomyces", "Acetobacter aceti", "Leuconostoc mesenteroides"], "a": 3, "e": "L. mesenteroides CO₂ (घोल फूलना) व lactic acid बनाता है; बाद में अन्य lactic acid bacteria भी सक्रिय होते हैं।", "s": "FP", "lv": "Moderate"}, {"q": "जेली बनाते समय उसके पूर्ण होने (end point) की जाँच हेतु कौन-सा परीक्षण किया जाता है?\nWhich test is used to judge the end point while making jelly?", "o": ["Iodine test", "Biuret test", "Sheet / flake test", "Phosphatase test"], "a": 2, "e": "चम्मच से गिराने पर जेली धार के बजाय परत (sheet/flake) बनाकर गिरे तो end point; refractometer से TSS भी देखते हैं।", "s": "FP", "lv": "Moderate"}, {"q": "फलों के रस को साफ़ (clarification) करने के लिए प्रायः कौन-सा एंजाइम प्रयोग होता है?\nWhich enzyme is commonly used for clarification of fruit juice?", "o": ["Lactase", "Pectinase", "Lipase", "Protease"], "a": 1, "e": "Pectinase pectin तोड़कर रस की viscosity व धुंधलापन घटाता है, जिससे रस निकलने की मात्रा भी बढ़ती है।", "s": "FP", "lv": "Moderate"}, {"q": "आड़ू व टमाटर जैसे फलों के लाई पीलिंग (Lye peeling) में क्या प्रयोग होता है?\nWhat is used in lye peeling of fruits like peach and tomato?", "o": ["गर्म NaOH विलयन", "सिरका", "Ethanol", "ठंडा नमक पानी"], "a": 0, "e": "गर्म सोडियम हाइड्रॉक्साइड (लगभग 1 - 3%) छिलका ढीला करता है, फिर पानी से धोकर क्षार हटाया जाता है।", "s": "FP", "lv": "Moderate"}, {"q": "फ्रीज़ ड्राइंग (Freeze drying) किस सिद्धांत पर आधारित है?\nFreeze drying is based on the principle of:", "o": ["ऊर्ध्वपातन / Sublimation", "आसवन / Distillation", "वाष्पन / Evaporation", "अवक्षेपण / Precipitation"], "a": 0, "e": "जमे हुए खाद्य से निर्वात में बर्फ सीधे वाष्प बनती है; स्वाद, रंग व पोषण सर्वोत्तम बचते हैं पर लागत अधिक।", "s": "FP", "lv": "Easy"}, {"q": "दूध पाउडर बनाने में सर्वाधिक प्रयुक्त सुखाने की विधि कौन-सी है?\nThe most widely used drying method for milk powder is:", "o": ["Tray drying", "Spray drying", "Freeze drying", "Sun drying"], "a": 1, "e": "Spray drier में गाढ़ा दूध बारीक बूँदों में गर्म हवा में छिड़का जाता है, कुछ सेकंड में पाउडर बनता है।", "s": "FP", "lv": "Easy"}, {"q": "मसालों की क्रायोजेनिक पिसाई (Cryogenic grinding) का मुख्य लाभ क्या है?\nThe main advantage of cryogenic grinding of spices is:", "o": ["नमी बढ़ना", "पिसाई में बनने वाली ऊष्मा से वाष्पशील तेल (volatile oil) की हानि रोकना", "सूक्ष्मजीव बढ़ना", "रंग गहरा होना"], "a": 1, "e": "तरल नाइट्रोजन से ठंडा करने पर मसाला भंगुर होता है और पिसाई का ताप कम रहता है, जिससे सुगंधित तेल बचा रहता है।", "s": "FP", "lv": "Hard"}, {"q": "सफ़ेद मिर्च (White pepper) काली मिर्च से कैसे भिन्न तरीके से बनती है?\nHow is white pepper prepared differently from black pepper?", "o": ["हरी अवस्था में सुखाकर", "धुएँ में सुखाकर", "पके दानों को पानी में सड़ाकर (retting) बाहरी छिलका हटाकर", "नमक में भिगोकर"], "a": 2, "e": "काली मिर्च: हरे दाने सुखाने पर enzymatic browning से काली; सफ़ेद मिर्च: पके दानों का pericarp retting से हटाकर।", "s": "FP", "lv": "Moderate"}, {"q": "हल्दी की क्योरिंग (Curing) में मुख्य रूप से क्या किया जाता है?\nCuring of turmeric mainly involves:", "o": ["फ्रीज़ करना", "प्रकंदों को उबालकर फिर सुखाना", "किण्वन करना", "धुएँ में रखना"], "a": 1, "e": "उबालने से starch gelatinize होता है, रंग समान फैलता है और कच्ची गंध जाती है; फिर सुखाकर polishing की जाती है।", "s": "FP", "lv": "Moderate"}, {"q": "सुरिमी (Surimi) क्या है?\nWhat is surimi?", "o": ["धोया हुआ बारीक कीमा किया मछली मांस (myofibrillar protein concentrate)", "सूखी नमकीन मछली", "किण्वित मछली सॉस", "मछली का तेल"], "a": 0, "e": "Surimi धुले मछली कीमे से बनता है, cryoprotectants (sugar, sorbitol) मिलाकर जमाया जाता है; इससे crab sticks आदि बनते हैं।", "s": "FP", "lv": "Moderate"}, {"q": "पोल्ट्री प्रसंस्करण में पंख निकालने (defeathering) से पहले पक्षी को गर्म पानी में डुबाने की क्रिया क्या कहलाती है?\nIn poultry processing, dipping birds in hot water before defeathering is called:", "o": ["Evisceration", "Stunning", "Chilling", "Scalding"], "a": 3, "e": "Scalding से पंखों की जड़ ढीली होती है; stunning वध से पहले, evisceration अंतड़ियाँ निकालना है।", "s": "FP", "lv": "Easy"}, {"q": "मांस निरीक्षण (Meat inspection) के दो मुख्य चरण कौन-से हैं?\nWhat are the two main stages of meat inspection?", "o": ["Curing व Smoking", "Ante-mortem व Post-mortem", "Chilling व Freezing", "Grading व Packing"], "a": 1, "e": "Ante-mortem (वध से पहले जीवित पशु की जाँच) व post-mortem (वध के बाद शव व अंगों की जाँच) से रोगग्रस्त मांस रोका जाता है।", "s": "FP", "lv": "Easy"}, {"q": "FSSAI मानकों के अनुसार डबल टोंड दूध (Double toned milk) में न्यूनतम वसा कितनी होनी चाहिए?\nAs per FSSAI standards, the minimum fat in double toned milk is:", "o": ["1.5%", "4.5%", "0.5%", "3.0%"], "a": 0, "e": "Double toned: वसा 1.5%, SNF 9.0%; toned: वसा 3.0%, SNF 8.5%; skimmed: वसा 0.5% से अधिक नहीं।", "s": "FP", "lv": "Moderate"}, {"q": "किसी नए खाद्य उत्पाद के विकास (new product development) का अंतिम चरण कौन-सा है?\nWhich is the final stage of new food product development?", "o": ["Idea generation", "Screening", "Commercialization (व्यावसायिक लॉन्च)", "Test marketing"], "a": 2, "e": "क्रम: idea generation → screening → concept testing → product development → test marketing → commercialization।", "s": "FP", "lv": "Moderate"}, {"q": "संवेदी मूल्यांकन (Sensory evaluation) में ट्रायंगल टेस्ट (Triangle test) का उपयोग किसके लिए होता है?\nIn sensory evaluation, the triangle test is used to:", "o": ["दो नमूनों में अंतर है या नहीं, यह पता करना", "पोषण मान बताना", "pH मापना", "उत्पाद की पसंद का स्तर मापना"], "a": 0, "e": "Triangle test एक difference test है: तीन नमूनों में दो समान व एक भिन्न, पैनलिस्ट भिन्न नमूना पहचानता है।", "s": "FP", "lv": "Moderate"}]}]);
